// v3rb01_fetching_by_hand / ex1 - reference solution.
import { useEffect, useReducer, useRef } from "react";

export type Resource<T> =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "error"; error: Error };

type Action<T> =
  | { type: "idle" }
  | { type: "start"; seq: number }
  | { type: "ok"; seq: number; data: T }
  | { type: "fail"; seq: number; error: Error };

// `seq` is bookkeeping, so it lives beside the view rather than inside it:
// callers should never have to know a request counter exists.
type Internal<T> = { seq: number; view: Resource<T> };

function reduce<T>(state: Internal<T>, action: Action<T>): Internal<T> {
  switch (action.type) {
    case "idle":
      return { seq: state.seq, view: { status: "idle" } };
    case "start":
      return { seq: action.seq, view: { status: "loading" } };
    case "ok":
      // An answer from a retired request is not an error - it is simply not
      // news. Dropping it here protects every caller, including the ones that
      // have no effect cleanup to hide behind.
      if (action.seq !== state.seq) return state;
      return { seq: state.seq, view: { status: "success", data: action.data } };
    case "fail":
      if (action.seq !== state.seq) return state;
      return { seq: state.seq, view: { status: "error", error: action.error } };
  }
}

function toError(reason: unknown): Error {
  return reason instanceof Error ? reason : new Error(String(reason));
}

export function useResource<T>(
  key: string | null,
  load: (key: string) => Promise<T>,
): Resource<T> {
  const [state, dispatch] = useReducer(reduce<T>, {
    seq: 0,
    view: { status: "idle" },
  } as Internal<T>);

  // `load` is frequently an inline arrow at the call site. Depending on it
  // would restart the request on every render of the parent, so it is read
  // through a ref that the effect never depends on.
  const loadRef = useRef(load);
  useEffect(() => {
    loadRef.current = load;
  });

  const seqRef = useRef(0);

  useEffect(() => {
    if (key === null) {
      seqRef.current += 1; // retire whatever was in flight
      dispatch({ type: "idle" });
      return;
    }

    const seq = (seqRef.current += 1);
    dispatch({ type: "start", seq });

    loadRef.current(key).then(
      (data) => dispatch({ type: "ok", seq, data }),
      (reason: unknown) => dispatch({ type: "fail", seq, error: toError(reason) }),
    );
  }, [key]);

  return state.view;
}

