// v3rb01_fetching_by_hand / ex2 - reference solution.

/**
 * An HTTP response that arrived and said no. The status and the parsed body
 * are both on the error because callers need them to decide between showing a
 * message, retrying, re-authenticating and staying silent.
 */
export class HttpError extends Error {
  readonly status: number;
  readonly body: unknown;

  constructor(status: number, body: unknown) {
    super(`HTTP ${status}`);
    this.name = "HttpError";
    this.status = status;
    this.body = body;
  }
}

type Parsed = { ok: true; value: unknown } | { ok: false };

function parse(text: string): Parsed {
  // An empty body is not malformed JSON - a 204, or a 200 from an endpoint
  // that returns nothing, both look like this.
  if (text.trim() === "") return { ok: true, value: null };
  try {
    return { ok: true, value: JSON.parse(text) as unknown };
  } catch {
    return { ok: false };
  }
}

export async function fetchJson<T>(url: string, init?: RequestInit): Promise<T> {
  // Deliberately not wrapped in try/catch. A rejection here is a transport
  // failure (TypeError) or an abort (DOMException named AbortError), and both
  // are the caller's business, not ours to reinterpret.
  const res = await fetch(url, init);

  // The body may only be read once, so read it in its most permissive form
  // and derive everything from the string.
  const text = await res.text();
  const parsed = parse(text);

  if (!res.ok) {
    // A failing response still carries information - a 422's validation map is
    // the whole reason the caller asked. If it will not parse, hand back the
    // raw text rather than losing it.
    throw new HttpError(res.status, parsed.ok ? parsed.value : text);
  }

  if (!parsed.ok) {
    throw new Error(`Invalid JSON in response from ${url}`);
  }

  return parsed.value as T;
}

// v3rb01_fetching_by_hand / ex3 - reference solution.
import { useEffect, useState, type JSX } from "react";

export function ReportView({
  reportId,
  range,
  fetchReport,
}: {
  reportId: string;
  range: string;
  fetchReport: (reportId: string, range: string) => Promise<string[]>;
}): JSX.Element {
  const [rows, setRows] = useState<string[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // Adjust state during render rather than in an effect: when the *identity*
  // of the report changes, what is on screen is not a stale version of the new
  // thing, it is a confident rendering of the wrong thing. React re-runs this
  // component before touching the DOM, so nothing flashes.
  const [seenId, setSeenId] = useState(reportId);
  if (seenId !== reportId) {
    setSeenId(reportId);
    setRows(null);
    setError(null);
  }

  useEffect(() => {
    let live = true;
    setBusy(true);
    // A new request invalidates the previous error immediately; keeping it
    // would let an alert outlive the request that produced it.
    setError(null);

    fetchReport(reportId, range).then(
      (next) => {
        if (!live) return;
        setRows(next);
        setBusy(false);
      },
      (reason: unknown) => {
        if (!live) return;
        setRows(null);
        setError(reason instanceof Error ? reason.message : String(reason));
        setBusy(false);
      },
    );

    return () => {
      live = false;
    };
    // fetchReport is injected and stable for the life of the component; the
    // request identity is (reportId, range).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reportId, range]);

  if (error !== null) {
    return <p role="alert">{error}</p>;
  }

  // Nothing to show yet: this is loading, and it gets a live region.
  if (rows === null) {
    return <p role="status">Loading report</p>;
  }

  // Something to show and possibly something newer coming: this is fetching,
  // and it gets aria-busy - visible, not announced, not disruptive.
  return (
    <div aria-busy={busy ? "true" : "false"}>
      <ul>
        {rows.map((row) => (
          <li key={row}>{row}</li>
        ))}
      </ul>
    </div>
  );
}

