// v3rb01_fetching_by_hand / ex4 - reference solution.
import { useEffect, useState, type JSX } from "react";

type View =
  | { kind: "loading" }
  | { kind: "quote"; text: string }
  | { kind: "error"; message: string };

export function QuotePanel({
  symbol,
  timeoutMs,
  fetchQuote,
}: {
  symbol: string;
  timeoutMs: number;
  fetchQuote: (symbol: string, signal: AbortSignal) => Promise<string>;
}): JSX.Element {
  const [view, setView] = useState<View>({ kind: "loading" });

  useEffect(() => {
    setView({ kind: "loading" });

    // Two independent reasons to stop. The controller is ours (unmount or a
    // new symbol); the timeout signal is the deadline. Both must reach the
    // same request, so they are composed into one.
    const controller = new AbortController();
    const deadline = AbortSignal.timeout(timeoutMs);
    const signal = AbortSignal.any([controller.signal, deadline]);

    fetchQuote(symbol, signal).then(
      (text) => {
        if (signal.aborted) return;
        setView({ kind: "quote", text });
      },
      (reason: unknown) => {
        // Asymmetric on purpose. Walking away is not news; a deadline is.
        if (controller.signal.aborted) return;

        if (deadline.aborted) {
          setView({ kind: "error", message: `Timed out loading ${symbol}` });
          return;
        }

        setView({
          kind: "error",
          message: reason instanceof Error ? reason.message : String(reason),
        });
      },
    );

    return () => {
      controller.abort();
    };
  }, [symbol, timeoutMs, fetchQuote]);

  if (view.kind === "loading") {
    return <p role="status">Loading {symbol}</p>;
  }
  if (view.kind === "error") {
    return <p role="alert">{view.message}</p>;
  }
  return <p>{view.text}</p>;
}

exercises.hints:
## Hint 1

The reason a naive retry loop leaks is that a sleep is a promise nothing can
interrupt. `await new Promise(r => setTimeout(r, ms))` resolves in `ms`
milliseconds no matter what the world does in the meantime. Your sleep needs a
second way to settle.

## Hint 2

```tsx
function sleep(ms: number, signal: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal.aborted) return reject(signal.reason);
    const timer = setTimeout(resolve, ms);
    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(signal.reason);
    }, { once: true });
  });
}
```

The `signal.aborted` check at the top matters: `addEventListener("abort", ...)`
on an already-aborted signal never fires, and the promise would hang for `ms`
and then resolve as if nothing happened.

## Hint 3

Three questions the loop asks, in order, and getting the order wrong is the
usual bug. Before an attempt: is the signal already aborted? After a failure:
did *we* cause this by aborting — if so rethrow, do not classify it as
retryable. Then: is this error worth another try? Only if all three say
"continue" do you sleep, and the sleep can itself reject, which ends the loop
without a further attempt.

references.solution.tsx:
// v3rb01_fetching_by_hand / ex5 - reference solution.
import { HttpError } from "../ex2/solution";

/**
 * Whether another identical attempt could plausibly succeed. A 422 was
 * understood and rejected; sending it again just produces a second rejection.
 */
export function isRetryable(error: unknown): boolean {
  // fetch rejects with a TypeError when no response was obtained at all -
  // DNS, connection reset, offline. Those are the retryable ones.
  if (error instanceof TypeError) return true;

  if (error instanceof HttpError) {
    if (error.status === 408 || error.status === 429) return true;
    return error.status >= 500;
  }

  return false;
}

/** A wait that can be cut short. Rejects with the signal's reason on abort. */
function sleep(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise<void>((resolve, reject) => {
    // An "abort" listener added to an already-aborted signal never fires, so
    // this early check is the difference between rejecting now and hanging
    // for the full delay.
    if (signal.aborted) {
      reject(signal.reason);
      return;
    }

    const timer = setTimeout(resolve, ms);

    signal.addEventListener(
      "abort",
      () => {
        clearTimeout(timer);
        reject(signal.reason);
      },
      // Without `once` the listeners accumulate one per attempt, and a signal
      // shared across a long-lived resource eventually warns about a leak.
      { once: true },
    );
  });
}

export async function withRetry<T>(
  attempt: (signal: AbortSignal) => Promise<T>,
  {
    signal,
    tries = 3,
    baseMs = 100,
  }: { signal: AbortSignal; tries?: number; baseMs?: number },
): Promise<T> {
  let lastError: unknown;

  for (let i = 0; i < tries; i++) {
    // Time passed inside the loop - during the previous attempt and during the
    // sleep - so the question has to be asked again here, not once up front.
    signal.throwIfAborted();

    try {
      return await attempt(signal);
    } catch (error) {
      // Our own cancellation is not a failure to classify or retry.
      if (signal.aborted) throw error;
      if (!isRetryable(error)) throw error;

      lastError = error;
      if (i === tries - 1) break;

      // Exponential growth spreads one client's retries out in time; the
      // jitter factor de-synchronises this client from every other one.
      const delay = baseMs * 2 ** i * (0.5 + Math.random());
      await sleep(delay, signal);
    }
  }

  throw lastError;
}

// v3rb01_fetching_by_hand / ex6 - reference solution.
import { useEffect, useState } from "react";

// Module-level on purpose: the sharing window has to span components, so it
// cannot live in a ref or in state.
const inFlight = new Map<string, Promise<unknown>>();

/**
 * Collapse concurrent callers of the same key onto one request. NOT a cache:
 * the entry lives exactly as long as the request does.
 */
export function dedupe<T>(key: string, run: () => Promise<T>): Promise<T> {
  const existing = inFlight.get(key) as Promise<T> | undefined;
  if (existing) return existing;

  // The map is written synchronously, before any await, so every caller in
  // this same turn of the event loop finds it.
  const promise = run().finally(() => {
    inFlight.delete(key);
  });

  inFlight.set(key, promise);
  return promise;
}

export function inFlightCount(): number {
  return inFlight.size;
}

export function useShared<T>(
  key: string,
  run: () => Promise<T>,
): { data: T | null; error: Error | null } {
  const [state, setState] = useState<{ data: T | null; error: Error | null }>({
    data: null,
    error: null,
  });

  useEffect(() => {
    let live = true;
    setState({ data: null, error: null });

    // No abort here, deliberately. The request is shared; cancelling it on
    // behalf of one subscriber would rob the others. This guard drops the
    // answer for this subscriber only.
    dedupe(key, run).then(
      (data) => {
        if (live) setState({ data, error: null });
      },
      (reason: unknown) => {
        if (!live) return;
        setState({
          data: null,
          error: reason instanceof Error ? reason : new Error(String(reason)),
        });
      },
    );

    return () => {
      live = false;
    };
    // `run` is a closure recreated every render at most call sites; the
    // request identity is the key.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  return state;
}

