// v3rb01_fetching_by_hand / ex8 - reference solution.
import { useCallback, useEffect, useRef, useState, type JSX } from "react";

type Item = { id: string; title: string };
type Page = { items: Item[]; next: string | null };

export function Feed({
  topic,
  fetchPage,
}: {
  topic: string;
  fetchPage: (
    topic: string,
    cursor: string | null,
    signal: AbortSignal,
  ) => Promise<Page>;
}): JSX.Element {
  const [items, setItems] = useState<Item[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const [done, setDone] = useState(false);
  const [busy, setBusy] = useState(false);

  // The generation of the *query*, not of a single request: a cursor advance
  // must not retire the pages already on screen, but a topic change must
  // retire everything.
  const gen = useRef(0);
  const controller = useRef<AbortController | null>(null);

  const load = useCallback(
    (from: string | null, myGen: number) => {
      controller.current?.abort();
      const own = new AbortController();
      controller.current = own;

      setBusy(true);
      fetchPage(topic, from, own.signal).then(
        (page) => {
          if (myGen !== gen.current) return;
          setItems((prev) => {
            // Servers repeat rows when the underlying data shifts between
            // pages. Two <li>s with the same key is a warning and a bug.
            const seen = new Set(prev.map((item) => item.id));
            return [...prev, ...page.items.filter((item) => !seen.has(item.id))];
          });
          setCursor(page.next);
          setDone(page.next === null);
          setBusy(false);
        },
        () => {
          if (myGen !== gen.current) return;
          setBusy(false);
        },
      );
    },
    [topic, fetchPage],
  );

  useEffect(() => {
    const myGen = (gen.current += 1);
    setItems([]);
    setCursor(null);
    setDone(false);
    load(null, myGen);

    return () => {
      // Retire the whole query, not just the request in flight.
      gen.current += 1;
      controller.current?.abort();
    };
  }, [load]);

  const loadMore = () => {
    // The disabled attribute is a UI affordance; this is the actual guard.
    if (busy || done) return;
    load(cursor, gen.current);
  };

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.title}</li>
        ))}
      </ul>

      {busy && items.length === 0 ? <p role="status">Loading</p> : null}

      {!done ? (
        <button type="button" onClick={loadMore} disabled={busy}>
          Load more
        </button>
      ) : null}

      {busy && items.length > 0 ? <p role="status">Loading more</p> : null}
    </div>
  );
}

