// v3rb01_fetching_by_hand / challenge - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

import { isRetryable, withRetry } from "../ex5/solution";

export type ResourceState<T> = {
  data: T | null;
  error: Error | null;
  isLoading: boolean;
  isFetching: boolean;
  refetch: () => void;
};

const toError = (reason: unknown): Error =>
  reason instanceof Error ? reason : new Error(String(reason));

export function useResource<T>({
  key,
  load,
  timeoutMs = 8000,
  tries = 2,
}: {
  key: string | null;
  load: (signal: AbortSignal) => Promise<T>;
  timeoutMs?: number;
  tries?: number;
}): ResourceState<T> {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<Error | null>(null);
  const [pending, setPending] = useState(false);

  // Refs, not state: none of these are rendered, and putting them in state
  // would put them in the effect's dependency array.
  const seqRef = useRef(0);
  const pendingRef = useRef(false);
  const controllerRef = useRef<AbortController | null>(null);
  const mountedRef = useRef(true);
  const loadRef = useRef(load);
  loadRef.current = load;

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  const run = useCallback(() => {
    const seq = (seqRef.current += 1);

    controllerRef.current?.abort();
    const controller = new AbortController();
    controllerRef.current = controller;

    const deadline = AbortSignal.timeout(timeoutMs);
    const signal = AbortSignal.any([controller.signal, deadline]);

    pendingRef.current = true;
    setPending(true);
    setError(null);

    // The composed signal goes into withRetry, so a timeout ends the loop
    // instead of being retried. Retrying past a deadline the user is already
    // waiting out is a choice, and this is the other one.
    withRetry((attemptSignal) => loadRef.current(attemptSignal), {
      signal,
      tries,
    }).then(
      (next) => {
        if (seq !== seqRef.current || !mountedRef.current) return;
        pendingRef.current = false;
        setData(next);
        setError(null);
        setPending(false);
      },
      (reason: unknown) => {
        if (seq !== seqRef.current || !mountedRef.current) return;
        // Walking away is not news. A deadline is.
        if (controller.signal.aborted) return;
        pendingRef.current = false;
        setPending(false);
        // Note what is NOT here: data is not cleared. On a refresh the user
        // keeps reading what they had; on a key change the effect below
        // already cleared it. One rule, two behaviours.
        setError(
          deadline.aborted
            ? new Error(`Request timed out after ${timeoutMs}ms`)
            : toError(reason),
        );
      },
    );
  }, [timeoutMs, tries]);

  useEffect(() => {
    // A new key is a different resource: what is on screen is not a stale
    // version of it, it is something else entirely.
    seqRef.current += 1;
    controllerRef.current?.abort();
    pendingRef.current = false;
    setData(null);
    setError(null);

    if (key === null) {
      setPending(false);
      return;
    }

    run();

    return () => {
      seqRef.current += 1;
      controllerRef.current?.abort();
    };
  }, [key, run]);

  const refetch = useCallback(() => {
    if (key === null) return;
    // Read the ref, not the state: the state value in this closure is one
    // render old, and two clicks inside one render would both pass.
    if (pendingRef.current) return;
    run();
  }, [key, run]);

  return {
    data,
    error,
    isLoading: pending && data === null,
    isFetching: pending,
    refetch,
  };
}

export function isRetryableError(error: unknown): boolean {
  return isRetryable(error);
}

// v3rb01_fetching_by_hand / review1 - reference solution.
import { useEffect, useId, useState, type JSX } from "react";

type Results = { query: string; items: string[] };

export function ProductSearch({
  search,
}: {
  search: (query: string, signal: AbortSignal) => Promise<string[]>;
}): JSX.Element {
  const inputId = useId();

  // Three clocks, three pieces of state. The input is instant, the query
  // trails it by the debounce, and the results trail the query by the network.
  const [input, setInput] = useState("");
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Results | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // Debounce: each keystroke's cleanup cancels the previous timer, so only the
  // final one in a burst survives. Same shape as retiring a request.
  useEffect(() => {
    const timer = setTimeout(() => setQuery(input.trim()), 300);
    return () => clearTimeout(timer);
  }, [input]);

  useEffect(() => {
    // The short-query branch lives inside the effect, not before it, so that
    // clearing the box runs the previous run's cleanup and aborts its request.
    if (query.length < 2) {
      setResults(null);
      setError(null);
      setBusy(false);
      return;
    }

    const controller = new AbortController();
    setBusy(true);
    setError(null);

    search(query, controller.signal).then(
      (items) => {
        if (controller.signal.aborted) return;
        // Results carry the query that produced them, so the "no matches"
        // message can never describe a search that was never run.
        setResults({ query, items });
        setBusy(false);
      },
      (reason: unknown) => {
        if (controller.signal.aborted) return;
        setResults(null);
        setError(reason instanceof Error ? reason.message : String(reason));
        setBusy(false);
      },
    );

    return () => {
      controller.abort();
    };
  }, [query, search]);

  return (
    <div>
      <label htmlFor={inputId}>Search products</label>
      <input
        id={inputId}
        value={input}
        onChange={(event) => setInput(event.target.value)}
      />

      {input.trim().length < 2 ? (
        <p role="status">Type at least two characters</p>
      ) : error !== null ? (
        <p role="alert">{error}</p>
      ) : results === null ? (
        <p role="status">Searching</p>
      ) : results.items.length === 0 ? (
        <p role="status">No matches for &quot;{results.query}&quot;</p>
      ) : (
        // Marked as refreshing rather than announced: the user is reading
        // these rows and does not need to be told about every keystroke.
        <ul aria-busy={busy ? "true" : "false"}>
          {results.items.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      )}
    </div>
  );
}

lessons.fullReadme:
# V3·RB2 — Caching, revalidation, and a query client you write

The archive version. Every part of the client, with the code, the mistakes,
the interview framing and a question bank.

## 1. The entry

```tsx
export type Entry<T = unknown> = {
  key: string;
  data: T | undefined;
  error: Error | undefined;
  updatedAt: number;        // 0 means "never successfully loaded"
  isFetching: boolean;
  promise: Promise<T> | undefined;   // for dedupe
};

export const isStale = (entry: Entry, staleTime: number, now = Date.now()) =>
  entry.updatedAt === 0 || now - entry.updatedAt > staleTime;
```

Two things this shape buys you. `data` and `error` coexist, which is what
lets a failed revalidation keep showing good data with a warning beside it —
the alternative, replacing data with the error, deletes information because a
request failed. And `updatedAt` makes staleness a *derived* fact rather than a
flag somebody has to remember to set.

## 2. The store and `useSyncExternalStore`

```tsx
class Store {
  private entries = new Map<string, Entry>();
  private listeners = new Map<string, Set<() => void>>();

  get(key: string): Entry | undefined {
    return this.entries.get(key);
  }

  set(key: string, patch: Partial<Entry>): void {
    const prev = this.entries.get(key) ?? blank(key);
    // A NEW object every time something changes, and the SAME object when
    // nothing does. This is the contract getSnapshot depends on.
    this.entries.set(key, { ...prev, ...patch });
    this.listeners.get(key)?.forEach((fn) => fn());
  }

  subscribe(key: string, fn: () => void): () => void {
    let set = this.listeners.get(key);
    if (!set) this.listeners.set(key, (set = new Set()));
    set.add(fn);
    return () => { set!.delete(fn); };
  }
}
```

Binding it:

```tsx
const subscribe = useCallback((fn: () => void) => store.subscribe(key, fn), [key]);
const getSnapshot = useCallback(() => store.get(key), [key]);
const entry = useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
```

The third argument is `getServerSnapshot`. Passing the same function is fine
when the store is safe to read on the server; omitting it throws during SSR.

**Why not context?** Context has no selector. A provider holding the whole
cache re-renders every consumer on every write, so one query updating re-renders
components subscribed to unrelated queries. `useSyncExternalStore` subscribes
per key, so only the interested components re-render. This is the entire reason
Zustand, Jotai, Redux and every query client are external stores rather than
context values.

## 3. Stale-while-revalidate

```tsx
function ensure<T>(key: string, fetcher: () => Promise<T>, staleTime: number) {
  const entry = store.get(key);

  if (entry?.promise) return entry.promise;                  // dedupe
  if (entry && !isStale(entry, staleTime)) return;           // fresh: nothing to do

  store.set(key, { isFetching: true });                      // note: data untouched
  const promise = fetcher().then(
    (data) => {
      store.set(key, {
        data: structuralShare(store.get(key)?.data, data),
        error: undefined,
        updatedAt: Date.now(),
        isFetching: false,
        promise: undefined,
      });
      return data;
    },
    (error: unknown) => {
      // Data survives a failed revalidation. It is old, not wrong.
      store.set(key, { error: toError(error), isFetching: false, promise: undefined });
      throw error;
    },
  );
  store.set(key, { promise });
  return promise;
}
```

The three cases and their UI:

| cache state | render | request |
| --- | --- | --- |
| miss | skeleton | yes |
| fresh hit | data | no |
| stale hit | data, `aria-busy` | yes |

## 4. Garbage collection

```tsx
subscribe(key: string, fn: () => void): () => void {
  clearTimeout(this.gcTimers.get(key));    // somebody is back: cancel eviction
  this.gcTimers.delete(key);
  // ... add listener
  return () => {
    set.delete(fn);
    if (set.size === 0) {
      this.gcTimers.set(key, setTimeout(() => {
        this.entries.delete(key);
        this.gcTimers.delete(key);
      }, this.gcTime));
    }
  };
}
```

The default in React Query is five minutes, and the number is chosen for a
specific interaction: a user opens a detail page, goes back, and opens it
again. That should be instant, and it is only instant if the entry outlives the
unmount. Evicting immediately turns your cache into a very complicated way of
not caching.

## 5. Invalidation

```tsx
invalidate(prefix: readonly string[]): void {
  for (const [key, entry] of this.entries) {
    if (!matches(key, prefix)) continue;
    this.set(key, { updatedAt: 0 });                 // stale, not deleted
    if (this.listeners.get(key)?.size) this.refetch(key);   // eager only if watched
  }
}
```

`updatedAt = 0` rather than `delete` is the important choice: deleting throws
away data the user is currently reading and replaces it with a spinner.
Marking it stale keeps it on screen while the truth is fetched.

The eager/lazy split is what makes this affordable. A mutation that invalidates
`["orders"]` in an app with 200 cached order pages triggers however many
requests there are visible components — usually one.

## 6. Structural sharing

```tsx
export function structuralShare<T>(prev: unknown, next: T): T {
  if (prev === next) return next;
  if (prev === null || next === null || typeof prev !== "object" || typeof next !== "object") {
    return next;
  }
  if (Array.isArray(prev) !== Array.isArray(next)) return next;

  const prevObj = prev as Record<string, unknown>;
  const nextObj = next as unknown as Record<string, unknown>;
  const keys = Object.keys(nextObj);

  let changed = keys.length !== Object.keys(prevObj).length;
  const merged: Record<string, unknown> = Array.isArray(next) ? ([] as never) : {};

  for (const k of keys) {
    const child = structuralShare(prevObj[k], nextObj[k]);
    merged[k] = child;
    if (child !== prevObj[k]) changed = true;
  }

  return (changed ? merged : prev) as T;
}
```

The payoff is measurable: with `React.memo` on the row component, a
revalidation of a 500-row table where nothing changed re-renders zero rows
instead of 500.

## 7. Focus and reconnect

```tsx
function install(client: QueryClient) {
  let last = 0;
  const maybe = () => {
    if (document.visibilityState !== "visible") return;
    if (Date.now() - last < 2000) return;     // floor
    last = Date.now();
    client.revalidateSubscribed();
  };
  window.addEventListener("visibilitychange", maybe);
  window.addEventListener("online", maybe);
  return () => {
    window.removeEventListener("visibilitychange", maybe);
    window.removeEventListener("online", maybe);
  };
}
```

One listener for the whole client, not one per query. And revalidate only
*subscribed* entries — a background tab that regains focus should not refetch
the two hundred entries nobody has looked at since Tuesday.

## 8. Writing to the cache

```tsx
setQueryData<T>(key: string, updater: T | ((prev: T | undefined) => T), at = Date.now()) {
  const entry = this.entries.get(key);
  if (entry && entry.updatedAt > at) return;    // this write is stale on arrival
  const prev = entry?.data as T | undefined;
  const next = typeof updater === "function" ? (updater as (p: T | undefined) => T)(prev) : updater;
  this.set(key, { data: structuralShare(prev, next), updatedAt: at, error: undefined });
}
```

The `updatedAt > at` guard fixes a bug that is very hard to find by reading
code and trivial to find once you know it exists: a background revalidation
started before your mutation, finished after it, and reverted the save.

## Common mistakes, ranked

1. `getSnapshot` returning a freshly constructed object — infinite loop.
2. Deleting entries on invalidation instead of marking them stale.
3. No `updatedAt`, so a slow response overwrites a fast one.
4. Evicting on unsubscribe with no grace period.
5. One focus listener per query.
6. Building the cache key with unsorted `JSON.stringify`.
7. Refetching every matching entry on invalidation, subscribed or not.
8. Replacing `data` with `error` on a failed revalidation.
9. Keeping the settled promise in the entry, turning dedupe into a permanent
   cache.
10. Putting the cache in context and wondering why the whole tree re-renders.

## The interview answer

*"What does `staleTime` do, and how is it different from `gcTime`?"*
`staleTime` is about **freshness**: how long an answer is trusted without
re-asking. While an entry is fresh, mounting a component that needs it triggers
no request at all. When it goes stale nothing is deleted — the data keeps
rendering, and the next time something asks for it, a background revalidation
starts. `gcTime` is about **lifetime**: how long an entry survives after its
last subscriber unmounted. The timer starts at zero subscribers and is
cancelled if anyone comes back. So `staleTime` controls requests, `gcTime`
controls memory, and the two most common misconfigurations are `staleTime: 0`
(a spinner on every navigation) and a short `gcTime` (back-navigation reloads
from scratch). If pressed for the deeper answer, add that this is the HTTP
`stale-while-revalidate` directive from RFC 5861 moved into the client, for the
same reason: the fastest response is the one you already have.

## Check yourself

1. Why does `getSnapshot` have to return a cached value?
2. What exactly happens at the instant `staleTime` elapses?
3. Which timer starts when the subscriber count reaches zero, and what cancels
   it?
4. Why mark entries stale on invalidation instead of deleting them?
5. Give a scenario where write-through produces wrong data.
6. Why does every cache write need a timestamp?
7. How does structural sharing differ from a deep-equality check?
8. Why is context the wrong home for a query cache?
9. Two components build the same filter object with keys in a different order.
   What goes wrong, and what is the symptom?
10. Why should focus revalidation have a minimum interval?
11. What should happen to `data` when a background revalidation fails?
12. Where does deduplication live in this design, and when is the entry's
    promise cleared?
13. Why refetch only subscribed entries on invalidation?
14. Your app polls every 5 seconds and the battery complains. What replaces the
    poll?

