// v3rb02_query_client / ex1 - reference solution.

export type Entry<T = unknown> = {
  key: string;
  data: T | undefined;
  error: Error | undefined;
  /** Timestamp of the last *successful* load. 0 means: never loaded. */
  updatedAt: number;
  isFetching: boolean;
};

export function blankEntry(key: string): Entry {
  return {
    key,
    data: undefined,
    error: undefined,
    updatedAt: 0,
    isFetching: false,
  };
}

/**
 * Staleness is derived, never stored. A stored flag would need somebody to
 * flip it when time passes, and nothing in the system runs when time passes.
 */
export function isStale(
  entry: Entry,
  staleTime: number,
  now: number = Date.now(),
): boolean {
  // Must come first: with staleTime Infinity, the comparison below would call
  // a never-loaded entry fresh and it would never be fetched at all.
  if (entry.updatedAt === 0) return true;

  // Strict >: staleTime 0 means "stale once any time has passed", not "stale
  // in the same millisecond it was written", which would loop.
  return now - entry.updatedAt > staleTime;
}

export function entryStatus(
  entry: Entry | undefined,
): "missing" | "loading" | "success" | "error" | "refetching" {
  if (entry === undefined) return "missing";

  // Precedence matters more than the individual checks.
  if (entry.isFetching) {
    return entry.data === undefined ? "loading" : "refetching";
  }

  // Data wins over error on purpose. A failed revalidation has not made the
  // data you already had wrong - it has only failed to confirm it. Replacing a
  // table with an error panel deletes information because a request failed.
  if (entry.data !== undefined) return "success";
  if (entry.error !== undefined) return "error";

  return "loading";
}

// v3rb02_query_client / ex2 - reference solution.
import { useCallback, useSyncExternalStore } from "react";

import { blankEntry, type Entry } from "../ex1/solution";

export class EntryStore {
  private entries = new Map<string, Entry>();
  private listeners = new Map<string, Set<() => void>>();

  get(key: string): Entry | undefined {
    // Returns whatever object is in the map. Because `set` is the only writer
    // and it always replaces, this reference is stable until something
    // actually changes - which is exactly what getSnapshot requires.
    return this.entries.get(key);
  }

  set(key: string, patch: Partial<Entry>): void {
    const prev = this.entries.get(key) ?? blankEntry(key);
    // New object every time, and only here. Never mutate an entry in place:
    // Object.is would then say nothing changed and React would not re-render.
    this.entries.set(key, { ...prev, ...patch });

    const set = this.listeners.get(key);
    if (!set) return;
    // Copy before iterating: a listener that unsubscribes during notification
    // would otherwise mutate the set being looped over.
    for (const listener of [...set]) listener();
  }

  subscribe(key: string, listener: () => void): () => void {
    let set = this.listeners.get(key);
    if (!set) {
      set = new Set();
      this.listeners.set(key, set);
    }
    set.add(listener);

    const owned = set;
    return () => {
      owned.delete(listener);
      // Drop the empty set, or a long-lived app accumulates one per key that
      // was ever subscribed.
      if (owned.size === 0) this.listeners.delete(key);
    };
  }

  listenerCount(key: string): number {
    return this.listeners.get(key)?.size ?? 0;
  }
}

export function useEntry(store: EntryStore, key: string): Entry | undefined {
  // Both callbacks must be stable. An inline `subscribe` tears down and
  // re-establishes the subscription on every render.
  const subscribe = useCallback(
    (listener: () => void) => store.subscribe(key, listener),
    [store, key],
  );

  const getSnapshot = useCallback(() => store.get(key), [store, key]);

  // The store is safe to read on the server, so the same reader serves as
  // getServerSnapshot. Omitting the third argument makes SSR throw.
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

// v3rb02_query_client / ex3 - reference solution.
import { isStale } from "../ex1/solution";
import { type EntryStore } from "../ex2/solution";

// Promises live beside the store, not inside the entry: an entry is a snapshot
// React compares by reference, and a promise is not something it can render.
const inFlight = new Map<string, Promise<unknown>>();

const toError = (reason: unknown): Error =>
  reason instanceof Error ? reason : new Error(String(reason));

export function ensureData<T>(
  store: EntryStore,
  key: string,
  fetcher: () => Promise<T>,
  { staleTime, now = Date.now }: { staleTime: number; now?: () => number },
): Promise<T> | undefined {
  // Dedupe first. A request already out for a stale entry should be joined,
  // not duplicated - checking freshness first would let a second caller start
  // a parallel request for the same key.
  const existing = inFlight.get(key) as Promise<T> | undefined;
  if (existing) return existing;

  const entry = store.get(key);
  if (entry && !isStale(entry, staleTime, now())) {
    // Fresh: the whole point of the cache is that this does nothing at all.
    return undefined;
  }

  // A merge patch, so `data` survives untouched. Replacing the entry here is
  // the mistake that produces a spinner flash on every revalidation.
  store.set(key, { isFetching: true });

  const promise = fetcher()
    .then(
      (data) => {
        store.set(key, {
          data,
          error: undefined,
          // Stamped when the answer arrived, not when the request left: a slow
          // request must not look fresher than it is.
          updatedAt: now(),
          isFetching: false,
        });
        return data;
      },
      (reason: unknown) => {
        // Data is deliberately absent from this patch. The previous answer is
        // unconfirmed, not wrong.
        store.set(key, { error: toError(reason), isFetching: false });
        // Rethrow: the store has recorded it, and the caller's own handler
        // still needs to fire.
        throw reason;
      },
    )
    .finally(() => {
      inFlight.delete(key);
    });

  inFlight.set(key, promise);
  return promise;
}

// v3rb02_query_client / ex4 - reference solution.
import { EntryStore } from "../ex2/solution";

export class GcStore extends EntryStore {
  private gcTime: number;
  private timers = new Map<string, ReturnType<typeof setTimeout>>();

  constructor({ gcTime = 300_000 }: { gcTime?: number } = {}) {
    super();
    this.gcTime = gcTime;
  }

  override subscribe(key: string, listener: () => void): () => void {
    // Cancel first, so the invariant is easy to state: while a key has
    // listeners, it has no pending eviction.
    this.cancelEviction(key);

    const unsubscribe = super.subscribe(key, listener);

    return () => {
      unsubscribe();
      // The timer belongs to the transition to zero, not to the entry.
      if (this.listenerCount(key) === 0) this.scheduleEviction(key);
    };
  }

  has(key: string): boolean {
    return this.get(key) !== undefined;
  }

  pendingEvictions(): number {
    return this.timers.size;
  }

  private scheduleEviction(key: string): void {
    if (this.timers.has(key)) return;
    const timer = setTimeout(() => {
      // Delete the record as well as the entry: a timer map that only grows is
      // a leak nothing surfaces until a heap snapshot.
      this.timers.delete(key);
      this.evict(key);
    }, this.gcTime);
    this.timers.set(key, timer);
  }

  private cancelEviction(key: string): void {
    const timer = this.timers.get(key);
    if (timer === undefined) return;
    clearTimeout(timer);
    this.timers.delete(key);
  }
}

// The base class gains one method rather than exposing its storage: eviction
// and storage are different concerns, and the subclass should not know how
// entries are held.
declare module "../ex2/solution" {
  interface EntryStore {
    evict(key: string): void;
  }
}

EntryStore.prototype.evict = function evict(this: EntryStore, key: string) {
  // Deliberately does not notify: nobody is listening, by construction.
  (this as unknown as { entries: Map<string, unknown> }).entries.delete(key);
};

