// v3rb02_query_client / challenge - reference solution.
import { useCallback, useEffect, useSyncExternalStore } from "react";

import { blankEntry, isStale, type Entry } from "../ex1/solution";
import { EntryStore } from "../ex2/solution";
import { matchesPrefix, serializeKey } from "../ex5/solution";
import { structuralShare } from "../ex6/solution";

export type QueryClient = ReturnType<typeof createQueryClient>;

export function createQueryClient({
  staleTime: defaultStaleTime = 0,
  gcTime = 300_000,
  now = Date.now,
}: { staleTime?: number; gcTime?: number; now?: () => number } = {}) {
  const store = new EntryStore();
  const entries = (store as unknown as { entries: Map<string, Entry> }).entries;

  const inFlight = new Map<string, Promise<unknown>>();
  // Invalidation knows a key but not how to fetch it. Without this map,
  // invalidateQueries can mark entries stale and never refetch anything.
  const fetchers = new Map<string, () => Promise<unknown>>();
  const gcTimers = new Map<string, ReturnType<typeof setTimeout>>();

  const toError = (reason: unknown): Error =>
    reason instanceof Error ? reason : new Error(String(reason));

  function evict(key: string) {
    entries.delete(key);
    // The closure's lifetime follows the entry's, or we leak one per key that
    // ever existed.
    fetchers.delete(key);
    gcTimers.delete(key);
  }

  function subscribe(key: string, listener: () => void): () => void {
    const timer = gcTimers.get(key);
    if (timer !== undefined) {
      clearTimeout(timer);
      gcTimers.delete(key);
    }

    const unsubscribe = store.subscribe(key, listener);

    return () => {
      unsubscribe();
      if (store.listenerCount(key) > 0) return;
      gcTimers.set(key, setTimeout(() => evict(key), gcTime));
    };
  }

  function run<T>(key: string, fetcher: () => Promise<T>): Promise<T> {
    const existing = inFlight.get(key) as Promise<T> | undefined;
    if (existing) return existing;

    fetchers.set(key, fetcher as () => Promise<unknown>);
    // Merge patch: data survives, so a revalidation never blanks the screen.
    store.set(key, { isFetching: true });

    const promise = fetcher()
      .then(
        (data) => {
          const prev = store.get(key)?.data;
          store.set(key, {
            data: structuralShare(prev, data),
            error: undefined,
            updatedAt: now(),
            isFetching: false,
          });
          return data;
        },
        (reason: unknown) => {
          // data deliberately untouched: unconfirmed, not wrong.
          store.set(key, { error: toError(reason), isFetching: false });
          throw reason;
        },
      )
      .finally(() => {
        inFlight.delete(key);
      });

    inFlight.set(key, promise);
    return promise;
  }

  function fetchQuery<T>(
    key: readonly unknown[],
    fetcher: () => Promise<T>,
    staleTime = defaultStaleTime,
  ): Promise<T> | undefined {
    const serialized = serializeKey(key);
    const entry = store.get(serialized);
    fetchers.set(serialized, fetcher as () => Promise<unknown>);

    if (inFlight.has(serialized)) return inFlight.get(serialized) as Promise<T>;
    if (entry && !isStale(entry, staleTime, now())) return undefined;

    return run(serialized, fetcher);
  }

  return {
    subscribe,

    getEntry: (key: string): Entry | undefined => store.get(key),

    getQueryData<T>(key: readonly unknown[]): T | undefined {
      return store.get(serializeKey(key))?.data as T | undefined;
    },

    setQueryData<T>(
      key: readonly unknown[],
      updater: T | ((prev: T | undefined) => T),
      at: number = now(),
    ): boolean {
      const serialized = serializeKey(key);
      const entry = store.get(serialized);
      if (entry && entry.updatedAt > at) return false;

      const prev = entry?.data as T | undefined;
      const next =
        typeof updater === "function"
          ? (updater as (previous: T | undefined) => T)(prev)
          : updater;

      store.set(serialized, {
        data: structuralShare(prev, next),
        error: undefined,
        updatedAt: at,
      });
      return true;
    },

    invalidateQueries(prefix: readonly unknown[]): void {
      for (const key of [...entries.keys()]) {
        if (!matchesPrefix(key, prefix)) continue;
        // Stale, not deleted: the user keeps reading what is on screen.
        store.set(key, { updatedAt: 0 });
        const fetcher = fetchers.get(key);
        // Eager only where somebody is looking.
        if (fetcher && store.listenerCount(key) > 0) void run(key, fetcher).catch(() => {});
      }
    },

    fetchQuery,
  };
}

export function useQuery<T>(
  client: QueryClient,
  key: readonly unknown[],
  fetcher: () => Promise<T>,
  { staleTime, enabled = true }: { staleTime?: number; enabled?: boolean } = {},
): {
  data: T | undefined;
  error: Error | undefined;
  isLoading: boolean;
  isFetching: boolean;
  refetch: () => void;
} {
  const serialized = serializeKey(key);

  const subscribe = useCallback(
    (listener: () => void) => client.subscribe(serialized, listener),
    [client, serialized],
  );
  const getSnapshot = useCallback(
    () => client.getEntry(serialized),
    [client, serialized],
  );

  // Subscribed even when disabled: the entry may be filled by another
  // component or by setQueryData, and this one should re-render when it is.
  const entry = useSyncExternalStore(subscribe, getSnapshot, getSnapshot) ??
    blankEntry(serialized);

  useEffect(() => {
    if (!enabled) return;
    // The error is already recorded in the store; an unhandled rejection here
    // would be noise, not information.
    void client.fetchQuery(key, fetcher, staleTime)?.catch(() => {});
    // The serialized key is the identity; `key` and `fetcher` are rebuilt
    // every render at every realistic call site.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [client, serialized, enabled, staleTime]);

  const refetch = useCallback(() => {
    void client.fetchQuery(key, fetcher, 0)?.catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [client, serialized]);

  return {
    data: entry.data as T | undefined,
    error: entry.error,
    isLoading: entry.isFetching && entry.data === undefined,
    isFetching: entry.isFetching,
    refetch,
  };
}

