// v3rb02_query_client / review1 - reference solution.

const byString = (a: unknown, b: unknown) => (String(a) < String(b) ? -1 : 1);

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value) as object | null;
  return proto === Object.prototype || proto === null;
}

/**
 * Turn a value into something JSON can represent faithfully. The four things
 * JSON.stringify gets wrong for cache keys - property order, undefined, Map,
 * Set - are all handled here rather than being discovered in production.
 */
function normalise(value: unknown, path: string): unknown {
  if (value === null) return null; // an explicitly cleared filter, kept
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") {
    return value;
  }

  if (value instanceof Date) return value.toISOString();

  // Sets have no order, so two sets with the same members must key the same.
  if (value instanceof Set) {
    return [...value].map((item, i) => normalise(item, `${path}[${i}]`)).sort(byString);
  }

  if (value instanceof Map) {
    return [...value]
      .map(([k, v]) => [normalise(k, path), normalise(v, path)])
      .sort((a, b) => byString(a[0], b[0]));
  }

  if (Array.isArray(value)) {
    // Arrays keep their order: [1,2] and [2,1] are different queries.
    return value.map((item, i) => normalise(item, `${path}[${i}]`));
  }

  if (isPlainObject(value)) {
    const out: Record<string, unknown> = {};
    for (const key of Object.keys(value).sort()) {
      const child = value[key];
      if (child === undefined) continue;
      out[key] = normalise(child, `${path}.${key}`);
    }
    return out;
  }

  // Loudly, at build-the-key time, on the first render in development - rather
  // than quietly, at serve-the-answer time, months later.
  throw new TypeError(
    `Cache key value at ${path} is not serialisable: ${Object.prototype.toString.call(value)}`,
  );
}

export function buildKey(
  base: string,
  params: Record<string, unknown>,
): readonly unknown[] {
  const normalised: Record<string, unknown> = {};

  // Sorted here as well as in normalise, because the top level is an object
  // too and property order is insertion order.
  for (const key of Object.keys(params).sort()) {
    const value = params[key];
    // undefined means "I did not filter by this"; null means "show me the ones
    // with no value". Different queries.
    if (value === undefined) continue;
    normalised[key] = normalise(value, key);
  }

  return [base, normalised];
}

const TIMESTAMP = /(^|\D)\d{13}(\D|$)/;

export function diagnose(keys: readonly string[]): {
  collisions: string[][];
  suspicious: string[];
} {
  const byValue = new Map<string, string[]>();
  for (const key of keys) {
    const group = byValue.get(key);
    if (group) group.push(key);
    else byValue.set(key, [key]);
  }

  const collisions = [...byValue.values()].filter((group) => group.length > 1);

  // A heuristic, and it reports rather than throws for that reason: a bare
  // 13-digit number is nearly always Date.now() leaking into a key, which is
  // the commonest cause of "my cache never hits" - but it could be an id.
  const suspicious = keys.filter((key) => TIMESTAMP.test(key));

  return { collisions, suspicious };
}

// v3rb03_suspense_streaming / ex1 - reference solution.
import { type JSX } from "react";

export type Resource<T> = {
  read: () => T;
  status: () => "pending" | "fulfilled" | "rejected";
};

/**
 * The primitive `use()` is built on. There is no third channel between a
 * component and React: it either returns elements or it throws. Throwing a
 * promise means "not yet"; throwing an error means "this failed".
 */
export function createResource<T>(promise: Promise<T>): Resource<T> {
  let status: "pending" | "fulfilled" | "rejected" = "pending";
  let value: T;
  let reason: unknown;

  // Attached eagerly, in the constructor body. A lazy version looks tidier and
  // leaves a promise that rejects before anyone reads it with no handler,
  // which Node reports as an unhandled rejection.
  const settled = promise.then(
    (resolved) => {
      status = "fulfilled";
      value = resolved;
    },
    (error: unknown) => {
      status = "rejected";
      reason = error;
    },
  );

  return {
    status: () => status,

    // Called during render, possibly many times before a commit. Synchronous,
    // idempotent, no side effects.
    read(): T {
      // `settled` rather than `promise`: it always fulfils, so React's retry
      // subscription cannot end up absorbing a rejection.
      if (status === "pending") throw settled;
      if (status === "rejected") throw reason;
      return value;
    },
  };
}

export function ValueOf<T>({ resource }: { resource: Resource<T> }): JSX.Element {
  return <p>{String(resource.read())}</p>;
}

// v3rb03_suspense_streaming / ex2 - reference solution.
import { Suspense, type JSX } from "react";

import { type Resource } from "../ex1/solution";

// The read happens HERE, one level below the boundary. Reading in Dashboard
// itself would suspend Dashboard, discarding the very boundaries meant to
// catch it - the boundary must be an ancestor in the committed tree.
function RevenueSection({ resource }: { resource: Resource<string> }): JSX.Element {
  return (
    <section aria-label="Revenue">
      <p>{resource.read()}</p>
    </section>
  );
}

function ListSection({
  label,
  resource,
}: {
  label: string;
  resource: Resource<string[]>;
}): JSX.Element {
  return (
    <section aria-label={label}>
      <ul>
        {resource.read().map((row) => (
          <li key={row}>{row}</li>
        ))}
      </ul>
    </section>
  );
}

export function Dashboard({
  revenue,
  orders,
  activity,
}: {
  revenue: Resource<string>;
  orders: Resource<string[]>;
  activity: Resource<string[]>;
}): JSX.Element {
  return (
    <>
      {/* No data dependency, so no boundary above it: this is the shell, and
          on the server it goes out in the first flush. */}
      <h1>Dashboard</h1>

      {/* Three independent units of "not ready yet". A slow region cannot hold
          up a fast one, and each is its own streaming flush point. */}
      <Suspense fallback={<p>Loading revenue</p>}>
        <RevenueSection resource={revenue} />
      </Suspense>

      <Suspense fallback={<p>Loading orders</p>}>
        <ListSection label="Orders" resource={orders} />
      </Suspense>

      <Suspense fallback={<p>Loading activity</p>}>
        <ListSection label="Activity" resource={activity} />
      </Suspense>
    </>
  );
}

/**
 * The contrast. One boundary turns three independent waits into one wait for
 * the slowest - including the heading, which needed no data at all.
 */
export function SlowDashboard({
  revenue,
  orders,
  activity,
}: {
  revenue: Resource<string>;
  orders: Resource<string[]>;
  activity: Resource<string[]>;
}): JSX.Element {
  return (
    <Suspense fallback={<p>Loading dashboard</p>}>
      <h1>Dashboard</h1>
      <RevenueSection resource={revenue} />
      <ListSection label="Orders" resource={orders} />
      <ListSection label="Activity" resource={activity} />
    </Suspense>
  );
}

