// v3rb03_suspense_streaming / review1 - reference solution.
import {
  Component,
  Suspense,
  createContext,
  use,
  useContext,
  type ErrorInfo,
  type JSX,
  type ReactNode,
} from "react";

const cache = new Map<string, Promise<string>>();

// The attempt number has to reach the reading component, and passing it as a
// prop would mean threading it through every layer between the boundary and
// the leaf. Context is what the boundary already scopes.
const AttemptContext = createContext(0);

const cacheKey = (id: string, attempt: number) => `${id}#${attempt}`;

function cached(
  id: string,
  attempt: number,
  load: (id: string, attempt: number) => Promise<string>,
): Promise<string> {
  const key = cacheKey(id, attempt);
  const existing = cache.get(key);
  if (existing) return existing;

  const promise = load(id, attempt);
  promise.catch(() => {
    // Drop the poisoned entry. Without this the attempt counter is the only
    // thing saving us, and the map leaks a rejected promise per failure.
    if (cache.get(key) === promise) cache.delete(key);
  });
  cache.set(key, promise);
  return promise;
}

export class RetryBoundary extends Component<
  {
    children: ReactNode;
    fallback: (props: { error: Error; retry: () => void }) => ReactNode;
  },
  { error: Error | null; attempt: number }
> {
  state: { error: Error | null; attempt: number } = { error: null, attempt: 0 };

  static getDerivedStateFromError(error: Error) {
    return { error };
  }

  componentDidCatch(_error: Error, _info: ErrorInfo) {
    // React 19 no longer re-throws caught errors to the console by default -
    // createRoot takes onCaughtError instead - so reporting belongs here.
  }

  private retry = () => {
    // Clearing the error alone would re-render children that immediately throw
    // the same cached rejection again: the alert would appear to be stuck.
    // Incrementing the attempt changes *what is asked*.
    this.setState((prev) => ({ error: null, attempt: prev.attempt + 1 }));
  };

  render() {
    if (this.state.error) {
      return this.props.fallback({ error: this.state.error, retry: this.retry });
    }
    // The key remounts the subtree, so a child that captured the old promise
    // in a ref or a useMemo cannot keep it.
    return (
      <AttemptContext.Provider value={this.state.attempt}>
        <div key={this.state.attempt}>{this.props.children}</div>
      </AttemptContext.Provider>
    );
  }
}

export function Panel({
  id,
  load,
}: {
  id: string;
  load: (id: string, attempt: number) => Promise<string>;
}): JSX.Element {
  // Reading the attempt here is what makes a retry ask a genuinely different
  // question: the cache key changes, so `use` gets a new promise rather than
  // the rejected one it threw last time.
  const attempt = useContext(AttemptContext);
  return <section aria-label={id}>{use(cached(id, attempt, load))}</section>;
}

export function ResilientPanel({
  id,
  load,
}: {
  id: string;
  load: (id: string, attempt: number) => Promise<string>;
}): JSX.Element {
  return (
    // Error boundary OUTSIDE, Suspense INSIDE. A rejection thrown from use()
    // passes the Suspense boundary (which only handles thenables) and reaches
    // the error boundary; the retry then remounts the Suspense boundary with
    // everything under it. The other order lets a fallback flash over the
    // error message.
    <RetryBoundary
      fallback={({ error, retry }) => (
        <div role="alert">
          <p>{error.message}</p>
          <button type="button" onClick={retry}>
            Retry
          </button>
        </div>
      )}
    >
      <Suspense fallback={<p>Loading</p>}>
        <Panel id={id} load={load} />
      </Suspense>
    </RetryBoundary>
  );
}

