// v3rb04_optimistic_updates / ex1 - reference solution.
import { useState, type JSX } from "react";

type Flag = { id: string; label: string; on: boolean };

type Props = {
  initial: Flag[];
  save: (id: string, on: boolean) => Promise<void>;
};

/**
 * The version most codebases contain. Correct for exactly one mutation at a
 * time, and quietly destructive the moment there are two.
 */
export function SnapshotFlags({ initial, save }: Props): JSX.Element {
  const [flags, setFlags] = useState(initial);
  const [failed, setFailed] = useState<string | null>(null);

  const toggle = async (flag: Flag) => {
    // The whole list, captured before the change. Everything that happens
    // between here and the catch is about to be thrown away.
    const snapshot = flags;
    const next = !flag.on;

    setFlags((prev) => prev.map((f) => (f.id === flag.id ? { ...f, on: next } : f)));
    setFailed(null);

    try {
      await save(flag.id, next);
    } catch {
      setFlags(snapshot);
      setFailed(flag.label);
    }
  };

  return (
    <div>
      <ul>
        {flags.map((flag) => (
          <li key={flag.id}>
            <button type="button" onClick={() => void toggle(flag)}>
              {flag.label}: {flag.on ? "on" : "off"}
            </button>
          </li>
        ))}
      </ul>
      {failed !== null ? <p role="status">Could not save {failed}</p> : null}
    </div>
  );
}

/**
 * The same thing, rolling back one change rather than one state. The
 * functional updater sees the list as it is at the moment of failure -
 * including anything that succeeded in between - and edits only its own row.
 */
export function LayeredFlags({ initial, save }: Props): JSX.Element {
  const [flags, setFlags] = useState(initial);
  const [failed, setFailed] = useState<string | null>(null);

  const toggle = async (flag: Flag) => {
    const next = !flag.on;

    setFlags((prev) => prev.map((f) => (f.id === flag.id ? { ...f, on: next } : f)));
    setFailed(null);

    try {
      await save(flag.id, next);
    } catch {
      // Undo the specific change. A toggle is its own inverse, so "undo" is
      // "set it back to !next"; for a non-involutive edit you would capture
      // the previous value of that one field - still a snapshot, but of the
      // right size.
      setFlags((prev) => prev.map((f) => (f.id === flag.id ? { ...f, on: !next } : f)));
      setFailed(flag.label);
    }
  };

  return (
    <div>
      <ul>
        {flags.map((flag) => (
          <li key={flag.id}>
            <button type="button" onClick={() => void toggle(flag)}>
              {flag.label}: {flag.on ? "on" : "off"}
            </button>
          </li>
        ))}
      </ul>
      {failed !== null ? <p role="status">Could not save {failed}</p> : null}
    </div>
  );
}

// v3rb04_optimistic_updates / ex2 - reference solution.
import { useOptimistic, useState, useTransition, type JSX } from "react";

export function LikeButton({
  postId,
  likes,
  onLiked,
  like,
}: {
  postId: string;
  likes: number;
  onLiked: (next: number) => void;
  like: (postId: string) => Promise<number>;
}): JSX.Element {
  const [, startTransition] = useTransition();
  const [failed, setFailed] = useState(false);

  // The reducer's "current" is the base with previous optimistic actions
  // already folded in, which is why three rapid clicks show +3 without any
  // extra bookkeeping.
  const [optimisticLikes, addOptimisticLike] = useOptimistic(
    likes,
    (current: number, delta: number) => current + delta,
  );

  const onClick = () => {
    // The dispatcher must run inside a transition: the optimistic action is
    // attached to the transition's lane. Outside one it is applied for a
    // single render and dropped, which is the "useOptimistic does nothing"
    // report.
    startTransition(async () => {
      setFailed(false);
      addOptimisticLike(1);

      try {
        const next = await like(postId);
        // Inside the transition, before it ends. When the transition
        // completes React discards the optimistic layer and renders from
        // `likes`; if the base has not moved yet, the old number shows for a
        // frame.
        onLiked(next);
      } catch {
        // useOptimistic has no failure state and cannot have one - a failed
        // action is simply one that gets dropped. Error UI is ordinary state.
        setFailed(true);
      }
    });
  };

  return (
    <div>
      <button type="button" onClick={onClick}>
        Like ({optimisticLikes})
      </button>
      {failed ? <p role="status">Could not like</p> : null}
    </div>
  );
}

