// v3rb04_optimistic_updates / ex3 - reference solution.
import { useActionState, useId, type JSX } from "react";

export type CommentState = {
  error: string | null;
  posted: string[];
  // Carried so a failed submission can put the user's text back: React resets
  // an uncontrolled form after any action that returns normally, including
  // one that returns an error.
  lastBody: string;
};

const MAX = 280;

export function CommentForm({
  createComment,
}: {
  createComment: (body: string) => Promise<string>;
}): JSX.Element {
  const bodyId = useId();

  const [state, formAction, isPending] = useActionState<CommentState, FormData>(
    async (previous, formData) => {
      // get() returns string | File | null. Coerce deliberately: a File
      // reaching a length check as [object File] is a memorable afternoon.
      const body = String(formData.get("body") ?? "");

      // Validation lives inside the action rather than guarding it, so
      // "invalid" travels the same channel as every other outcome.
      if (body.trim() === "") {
        return { error: "Comment cannot be empty", posted: previous.posted, lastBody: body };
      }
      if (body.length > MAX) {
        return { error: "Comment is too long", posted: previous.posted, lastBody: body };
      }

      try {
        const saved = await createComment(body);
        return { error: null, posted: [...previous.posted, saved], lastBody: "" };
      } catch (error) {
        // Never throw: the action's return value IS the new state, and a throw
        // escapes to the nearest error boundary instead of updating it.
        return {
          error: error instanceof Error ? error.message : String(error),
          posted: previous.posted,
          lastBody: body,
        };
      }
    },
    { error: null, posted: [], lastBody: "" },
  );

  return (
    <div>
      <form action={formAction}>
        <label htmlFor={bodyId}>Comment</label>
        <textarea id={bodyId} name="body" defaultValue={state.lastBody} />
        {/* Queuing, not blocking, is useActionState's default - so guarding
            against a double post is still our job. */}
        <button type="submit" disabled={isPending}>
          Post
        </button>
      </form>

      {state.error !== null ? <p role="alert">{state.error}</p> : null}

      <ul>
        {state.posted.map((comment) => (
          <li key={comment}>{comment}</li>
        ))}
      </ul>
    </div>
  );
}

// v3rb04_optimistic_updates / ex4 - reference solution.
import { useId, useState, type JSX } from "react";

type Task = {
  /** React identity. Chosen once, never changes, also sent as the record id. */
  clientId: string;
  /** Server identity. Data: it goes in links and requests, not in keys. */
  serverId: string | null;
  title: string;
};

export function TaskList({
  create,
  newId,
}: {
  create: (clientId: string, title: string) => Promise<{ id: string }>;
  newId: () => string;
}): JSX.Element {
  const inputId = useId();
  const [title, setTitle] = useState("");
  const [tasks, setTasks] = useState<Task[]>([]);
  const [failed, setFailed] = useState<string | null>(null);

  const add = async () => {
    const trimmed = title.trim();
    if (trimmed === "") return;

    const clientId = newId();
    setTasks((prev) => [...prev, { clientId, serverId: null, title: trimmed }]);
    setTitle("");
    setFailed(null);

    try {
      // The client's id is the record's id: a retried POST after a lost
      // response cannot create a duplicate, which is what makes writes safe
      // to retry at all.
      const saved = await create(clientId, trimmed);
      setTasks((prev) =>
        prev.map((task) =>
          task.clientId === clientId ? { ...task, serverId: saved.id } : task,
        ),
      );
    } catch {
      setTasks((prev) => prev.filter((task) => task.clientId !== clientId));
      setFailed(trimmed);
    }
  };

  return (
    <div>
      <label htmlFor={inputId}>Title</label>
      <input
        id={inputId}
        value={title}
        onChange={(event) => setTitle(event.target.value)}
      />
      <button type="button" onClick={() => void add()}>
        Add
      </button>

      <ul>
        {tasks.map((task) => (
          // key={task.serverId ?? task.clientId} is the mistake: the key would
          // change the moment the server answers, remounting the row and
          // discarding focus, uncontrolled input values and animations.
          <li key={task.clientId} data-pending={task.serverId === null ? "true" : "false"}>
            <span>{task.title}</span>
            <input defaultValue={task.title} />
            <button type="button">Rename {task.title}</button>
          </li>
        ))}
      </ul>

      {failed !== null ? <p role="status">Could not create {failed}</p> : null}
    </div>
  );
}

