## Exercise 5 — concurrent mutations, independent rollback

Edit `ex5/solution.tsx`. Build the layer model explicitly.

```tsx
type Doc = { id: string; title: string };

export function useOptimisticLayer<T>(
  confirmed: T,
): {
  view: T;
  begin: (id: string, apply: (value: T) => T) => void;
  settle: (id: string, next?: T) => void;
  fail: (id: string) => void;
  pendingCount: number;
};

export function DocTitles({
  docs,
  rename,
}: {
  docs: Doc[];
  rename: (id: string, title: string) => Promise<void>;
}): JSX.Element;
```

`useOptimisticLayer` keeps `confirmed` plus an **ordered list** of pending
transformations. `view` is the fold of the list over `confirmed`.

- `begin(id, apply)` pushes an entry.
- `settle(id, next)` removes it, optionally replacing the confirmed base.
- `fail(id)` removes it and nothing else.
- Entries removed from the middle leave the rest applied, in order.

`DocTitles` renders each doc with an input and a `Save` button; saving applies
the rename optimistically through the layer and calls `rename`. A failure calls
`fail` and renders
`<p role="status">Could not rename {id}</p>`.

The gate saves doc `a` and doc `b`, resolves `b`, rejects `a`, and asserts `b`'s
new title is on screen and `a`'s original is back. It then starts three
renames, fails the middle one, and asserts the other two survive with their
order preserved. `pendingCount` must return to `0`.

```
uv run dojo test react v3rb04_optimistic_updates ex5
```

references.solution.tsx:
// v3rb04_optimistic_updates / ex5 - reference solution.
import { useCallback, useState, type JSX } from "react";

type Doc = { id: string; title: string };

type Pending<T> = { id: string; apply: (value: T) => T };

/**
 * useOptimistic with the transition machinery replaced by explicit lifecycle
 * calls: works outside transitions, at the cost of being able to leak an entry
 * if you forget to settle it.
 */
export function useOptimisticLayer<T>(confirmed: T): {
  view: T;
  begin: (id: string, apply: (value: T) => T) => void;
  settle: (id: string, next?: T) => void;
  fail: (id: string) => void;
  pendingCount: number;
} {
  // Base and layer live in one state object so a settle can move the base and
  // drop the entry in a single update - two updates would give a frame where
  // neither is applied, which the user sees as a flicker.
  const [state, setState] = useState<{ base: T; pending: Pending<T>[] }>({
    base: confirmed,
    pending: [],
  });

  const begin = useCallback((id: string, apply: (value: T) => T) => {
    setState((prev) => ({ ...prev, pending: [...prev.pending, { id, apply }] }));
  }, []);

  const settle = useCallback((id: string, next?: T) => {
    setState((prev) => ({
      base: next === undefined ? prev.base : next,
      pending: prev.pending.filter((entry) => entry.id !== id),
    }));
  }, []);

  const fail = useCallback((id: string) => {
    // Remove one entry. Everything else stays applied, because nothing else
    // was ever overwritten.
    setState((prev) => ({ ...prev, pending: prev.pending.filter((e) => e.id !== id) }));
  }, []);

  // The fold, in order: two edits to the same field apply in the order the
  // user made them, and removing the first still leaves the second on top of
  // the original value - which a snapshot design cannot express at all.
  const view = state.pending.reduce((acc, entry) => entry.apply(acc), state.base);

  return { view, begin, settle, fail, pendingCount: state.pending.length };
}

export function DocTitles({
  docs,
  rename,
}: {
  docs: Doc[];
  rename: (id: string, title: string) => Promise<void>;
}): JSX.Element {
  const { view, begin, settle, fail } = useOptimisticLayer<Doc[]>(docs);
  const [drafts, setDrafts] = useState<Record<string, string>>({});
  const [failed, setFailed] = useState<string | null>(null);

  const save = async (id: string) => {
    const title = drafts[id] ?? view.find((doc) => doc.id === id)?.title ?? "";
    const mutationId = `${id}:${Date.now()}:${Math.random()}`;

    begin(mutationId, (docsNow) =>
      docsNow.map((doc) => (doc.id === id ? { ...doc, title } : doc)),
    );
    setFailed(null);

    try {
      await rename(id, title);
      settle(mutationId);
    } catch {
      fail(mutationId);
      setFailed(id);
    }
  };

  return (
    <div>
      <ul>
        {view.map((doc) => (
          <li key={doc.id}>
            <input
              aria-label={`Title for ${doc.id}`}
              value={drafts[doc.id] ?? doc.title}
              onChange={(event) =>
                setDrafts((prev) => ({ ...prev, [doc.id]: event.target.value }))
              }
            />
            <button type="button" onClick={() => void save(doc.id)}>
              Save
            </button>
          </li>
        ))}
      </ul>
      {failed !== null ? <p role="status">Could not rename {failed}</p> : null}
    </div>
  );
}

