## Exercise 6 — the response that arrives too late

Edit `ex6/solution.tsx`. Export one component.

```tsx
type Status = "draft" | "review" | "published";

export function StatusPicker({
  initial,
  setStatus,
}: {
  initial: Status;
  setStatus: (next: Status) => Promise<Status>;
}): JSX.Element;
```

- Three buttons, one per status, labelled with the status. Clicking one shows
  it as selected **immediately** and calls `setStatus`.
- The current status renders in `<p data-testid="status">`.
- Every mutation carries an increasing version. When a response arrives:
  - if its version is **lower than the highest already applied**, drop it —
    **including a successful one**;
  - otherwise record the version and apply the server's returned status.
- A failure whose version is current reverts to the last confirmed status and
  renders `<p role="status">Could not set status</p>`. A failure from a
  superseded version is silent.

The gate clicks `review`, then `published`, resolves **`published` first**, then
`review`. The final status must be `published`. It then clicks `draft`, rejects
it, and asserts the revert lands on `published`, not on `initial`.

```
uv run dojo test react v3rb04_optimistic_updates ex6
```

references.solution.tsx:
// v3rb04_optimistic_updates / ex6 - reference solution.
import { useRef, useState, type JSX } from "react";

type Status = "draft" | "review" | "published";

const ALL: Status[] = ["draft", "review", "published"];

export function StatusPicker({
  initial,
  setStatus,
}: {
  initial: Status;
  setStatus: (next: Status) => Promise<Status>;
}): JSX.Element {
  // The base: only moves when a non-superseded response is applied. Reverting
  // to `initial` instead would undo every earlier success.
  const [confirmed, setConfirmed] = useState<Status>(initial);
  const [optimistic, setOptimistic] = useState<Status | null>(null);
  const [failed, setFailed] = useState(false);

  // Refs, not state: nothing renders them, and they must be read synchronously
  // inside a closure created several renders ago - a useState value read there
  // would be the version that was current at the time of the click.
  const issued = useRef(0);
  const applied = useRef(0);

  const choose = async (next: Status) => {
    const version = ++issued.current;
    setOptimistic(next);
    setFailed(false);

    try {
      const serverStatus = await setStatus(next);

      // Dropping a SUCCESSFUL response feels wrong and is the point: a success
      // is a true statement about a world that has since moved on.
      if (version < applied.current) return;

      applied.current = version;
      // The server is allowed to disagree - a validation rule may have
      // downgraded the request. Its answer is what becomes confirmed.
      setConfirmed(serverStatus);
      setOptimistic(null);
    } catch {
      if (version < applied.current) return; // a failure nobody is waiting for
      applied.current = version;
      setOptimistic(null);
      setFailed(true);
    }
  };

  const current = optimistic ?? confirmed;

  return (
    <div>
      {ALL.map((status) => (
        <button
          key={status}
          type="button"
          aria-pressed={current === status}
          onClick={() => void choose(status)}
        >
          {status}
        </button>
      ))}

      <p data-testid="status">{current}</p>
      {failed ? <p role="status">Could not set status</p> : null}
    </div>
  );
}

// v3rb04_optimistic_updates / ex7 - reference solution.
import { useEffect, useRef, useState, type JSX } from "react";

type Message = { id: string; subject: string };

export function Mailbox({
  initial,
  archive,
  windowMs = 5000,
}: {
  initial: Message[];
  archive: (id: string) => Promise<void>;
  windowMs?: number;
}): JSX.Element {
  const [messages, setMessages] = useState(initial);
  // Hidden, not deleted. Undo restores the exact position for free, because
  // the message never left the list.
  const [hidden, setHidden] = useState<Message | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const clear = () => {
    if (timer.current !== null) clearTimeout(timer.current);
    timer.current = null;
  };

  const commit = (message: Message) => {
    clear();
    setHidden(null);
    void archive(message.id).then(
      () => {
        setMessages((prev) => prev.filter((m) => m.id !== message.id));
      },
      () => {
        // The deferred request failed: the message was never really archived,
        // so it comes back and the user is told.
        setFailed(message.subject);
      },
    );
  };

  const startArchive = (message: Message) => {
    // Commit any open window first, synchronously, or there would briefly be
    // two hidden messages and a timer pointing at the wrong one.
    if (hidden !== null) commit(hidden);

    setFailed(null);
    setHidden(message);
    timer.current = setTimeout(() => commit(message), windowMs);
  };

  const undo = () => {
    // Nothing to undo - only something to cancel. That inversion is what makes
    // undo instant and reliable.
    clear();
    setHidden(null);
  };

  useEffect(() => clear, []);

  return (
    <div>
      <ul>
        {messages
          .filter((message) => message.id !== hidden?.id)
          .map((message) => (
            <li key={message.id}>
              <span>{message.subject}</span>
              <button type="button" onClick={() => startArchive(message)}>
                Archive {message.subject}
              </button>
            </li>
          ))}
      </ul>

      {hidden !== null ? (
        // Polite, not an alert: the action succeeded and nothing needs
        // interrupting.
        <div role="status">
          Archived {hidden.subject}
          <button type="button" onClick={undo}>
            Undo
          </button>
        </div>
      ) : null}

      {failed !== null ? <p role="alert">Could not archive {failed}</p> : null}
    </div>
  );
}

