// v3rb04_optimistic_updates / challenge - reference solution.
import {
  useActionState,
  useEffect,
  useId,
  useRef,
  useState,
  type JSX,
} from "react";

export type Todo = {
  clientId: string;
  serverId: string | null;
  title: string;
  done: boolean;
};

type Pending = { id: string; apply: (todos: Todo[]) => Todo[] };
type Failure = { rowId: string; label: string; run: () => Promise<void> };

const UNDO_MS = 5000;

export function TodoApp({
  initial,
  api,
  newId,
}: {
  initial: Todo[];
  api: {
    create: (clientId: string, title: string) => Promise<{ id: string }>;
    toggle: (clientId: string, done: boolean) => Promise<{ done: boolean }>;
    remove: (clientId: string) => Promise<void>;
  };
  newId: () => string;
}): JSX.Element {
  const titleId = useId();

  // Confirmed base and the layer of pending transformations, in one state
  // object so a settle can move both without an intermediate frame.
  const [state, setState] = useState<{ base: Todo[]; pending: Pending[] }>({
    base: initial,
    pending: [],
  });

  const [hidden, setHidden] = useState<Todo | null>(null);
  const [failure, setFailure] = useState<Failure | null>(null);

  // Per row, not global: a toggle of row b must not invalidate a response for
  // row a. Never rendered, so a ref.
  const versions = useRef(new Map<string, number>());
  const applied = useRef(new Map<string, number>());
  const undoTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      if (undoTimer.current !== null) clearTimeout(undoTimer.current);
    };
  }, []);

  const begin = (id: string, apply: (todos: Todo[]) => Todo[]) =>
    setState((prev) => ({ ...prev, pending: [...prev.pending, { id, apply }] }));

  const drop = (id: string, nextBase?: (todos: Todo[]) => Todo[]) =>
    setState((prev) => ({
      base: nextBase ? nextBase(prev.base) : prev.base,
      pending: prev.pending.filter((entry) => entry.id !== id),
    }));

  const todos = state.pending.reduce((acc, entry) => entry.apply(acc), state.base);

  // ---- add -----------------------------------------------------------------

  const [addState, addAction, isAdding] = useActionState<{ error: string | null }, FormData>(
    async (_prev, formData) => {
      const title = String(formData.get("title") ?? "").trim();
      if (title === "") return { error: "Title is required" };

      const clientId = newId();
      const mutationId = `create:${clientId}`;

      begin(mutationId, (rows) => [
        ...rows,
        { clientId, serverId: null, title, done: false },
      ]);

      const run = async () => {
        // The client's id IS the record's id, so a retried create cannot
        // duplicate - and the React key never has to change.
        const saved = await api.create(clientId, title);
        if (!mounted.current) return;
        drop(mutationId, (rows) => [
          ...rows,
          { clientId, serverId: saved.id, title, done: false },
        ]);
      };

      try {
        await run();
        return { error: null };
      } catch {
        drop(mutationId);
        // What gets stored is a closure, not a message: the retry button and
        // the announcement can then never disagree about what failed.
        setFailure({ rowId: clientId, label: title, run });
        return { error: null };
      }
    },
    { error: null },
  );

  // ---- toggle --------------------------------------------------------------

  const toggle = async (todo: Todo) => {
    const next = !todo.done;
    const version = (versions.current.get(todo.clientId) ?? 0) + 1;
    versions.current.set(todo.clientId, version);
    const mutationId = `toggle:${todo.clientId}:${version}`;

    begin(mutationId, (rows) =>
      rows.map((row) => (row.clientId === todo.clientId ? { ...row, done: next } : row)),
    );

    const run = async () => {
      const result = await api.toggle(todo.clientId, next);
      if (!mounted.current) return;
      // A successful response for a superseded click is a true statement about
      // a world that has moved on. Drop it.
      if (version < (applied.current.get(todo.clientId) ?? 0)) {
        drop(mutationId);
        return;
      }
      applied.current.set(todo.clientId, version);
      drop(mutationId, (rows) =>
        rows.map((row) =>
          row.clientId === todo.clientId ? { ...row, done: result.done } : row,
        ),
      );
    };

    try {
      await run();
    } catch {
      if (!mounted.current) return;
      // Only this entry is removed; a concurrent success on another row is
      // untouched because it was never overwritten.
      drop(mutationId);
      if (version >= (applied.current.get(todo.clientId) ?? 0)) {
        setFailure({ rowId: todo.clientId, label: todo.title, run });
      }
    }
  };

  // ---- delete with an undo window -----------------------------------------

  const commitDelete = (todo: Todo) => {
    if (undoTimer.current !== null) clearTimeout(undoTimer.current);
    undoTimer.current = null;
    setHidden(null);

    const run = async () => {
      await api.remove(todo.clientId);
      if (!mounted.current) return;
      drop(`delete:${todo.clientId}`, (rows) =>
        rows.filter((row) => row.clientId !== todo.clientId),
      );
    };

    void run().catch(() => {
      if (!mounted.current) return;
      setFailure({ rowId: todo.clientId, label: todo.title, run });
    });
  };

  const startDelete = (todo: Todo) => {
    if (hidden !== null) commitDelete(hidden);
    setHidden(todo);
    undoTimer.current = setTimeout(() => commitDelete(todo), UNDO_MS);
  };

  const undo = () => {
    if (undoTimer.current !== null) clearTimeout(undoTimer.current);
    undoTimer.current = null;
    // Nothing to restore: the row never left the list, only the render.
    setHidden(null);
  };

  const visible = todos.filter((todo) => todo.clientId !== hidden?.clientId);

  return (
    <div>
      <form action={addAction}>
        <label htmlFor={titleId}>Title</label>
        <input id={titleId} name="title" />
        <button type="submit" disabled={isAdding}>
          Add
        </button>
      </form>
      {addState.error !== null ? <p role="alert">{addState.error}</p> : null}

      <ul>
        {visible.map((todo) => (
          // clientId for the row's whole life. Keying by serverId ?? clientId
          // would remount the row at the moment of confirmation.
          <li
            key={todo.clientId}
            data-pending={todo.serverId === null ? "true" : "false"}
            data-failed={failure?.rowId === todo.clientId ? "true" : "false"}
          >
            <input
              type="checkbox"
              aria-label={todo.title}
              checked={todo.done}
              onChange={() => void toggle(todo)}
            />
            <span>{todo.title}</span>
            <button type="button" onClick={() => startDelete(todo)}>
              Delete {todo.title}
            </button>
            {failure?.rowId === todo.clientId ? (
              <button
                type="button"
                onClick={() => {
                  const retry = failure.run;
                  setFailure(null);
                  void retry().catch(() => setFailure(failure));
                }}
              >
                Retry
              </button>
            ) : null}
          </li>
        ))}
      </ul>

      {hidden !== null ? (
        <div role="status">
          Deleted {hidden.title}
          <button type="button" onClick={undo}>
            Undo
          </button>
        </div>
      ) : null}

      {/* Rendered always, empty when there is nothing to say: some screen
          readers do not announce a live region that appears already
          populated. */}
      <div aria-live="polite">
        {failure !== null ? `Could not save ${failure.label}` : ""}
      </div>
    </div>
  );
}

