// v3rb04_optimistic_updates / review1 - reference solution.
import { useRef, useState, type JSX } from "react";

export class ConflictError extends Error {
  readonly serverValue: number;

  constructor(serverValue: number) {
    super(`Conflict: server holds ${serverValue}`);
    this.name = "ConflictError";
    this.serverValue = serverValue;
  }
}

export function QuantityStepper({
  sku,
  initial,
  setQuantity,
  max,
}: {
  sku: string;
  initial: number;
  setQuantity: (
    sku: string,
    quantity: number,
    version: number,
  ) => Promise<{ quantity: number; version: number }>;
  max: number;
}): JSX.Element {
  const [confirmed, setConfirmed] = useState(initial);
  const [optimistic, setOptimistic] = useState<number | null>(null);
  const [conflict, setConflict] = useState<number | null>(null);
  const [failed, setFailed] = useState(false);

  // Server-supplied, not a client counter. A client counter can only ignore
  // your own stale responses; only a server version can tell you somebody
  // else changed the record between your read and your write.
  const version = useRef(0);
  const applied = useRef(0);
  const issued = useRef(0);

  // The invariant, enforced at the render boundary rather than at every
  // writer: the displayed quantity is always in [0, max], whatever anyone says.
  const clamp = (value: number) => Math.min(max, Math.max(0, value));
  const shown = clamp(optimistic ?? confirmed);

  const step = async (delta: number) => {
    const next = clamp(shown + delta);
    // A clamp is not a failure and not a conflict: the UI already prevented
    // it, so there is nothing to send and nothing to say.
    if (next === shown) return;

    const seq = ++issued.current;
    setOptimistic(next);
    setFailed(false);
    setConflict(null);

    try {
      const result = await setQuantity(sku, next, version.current);

      if (seq < applied.current) return; // superseded, even though it worked
      applied.current = seq;
      version.current = result.version;
      setConfirmed(clamp(result.quantity));
      setOptimistic(null);
    } catch (error) {
      if (seq < applied.current) return;
      applied.current = seq;
      setOptimistic(null);

      if (error instanceof ConflictError) {
        // The world changed underneath. Retrying would apply the user's intent
        // to a state they never saw - they wanted 3, someone set it to 10, and
        // a retry makes it 11. Snap to the truth and let them decide again.
        setConfirmed(clamp(error.serverValue));
        setConflict(error.serverValue);
        return;
      }

      // Transport failure: nothing changed, so revert quietly.
      setFailed(true);
    }
  };

  return (
    <div>
      <button type="button" disabled={shown <= 0} onClick={() => void step(-1)}>
        −
      </button>
      <span data-testid="qty">{shown}</span>
      <button type="button" disabled={shown >= max} onClick={() => void step(1)}>
        +
      </button>

      {/* An alert: the number changed to something the user did not choose and
          their next action depends on knowing. */}
      {conflict !== null ? (
        <p role="alert">Someone else set the quantity to {conflict}</p>
      ) : null}

      {/* Polite: the value went back to what it was, nothing surprising
          happened, and interrupting would be noise. */}
      {failed ? <p role="status">Could not update</p> : null}
    </div>
  );
}

exercises.hints:
## Hint 1

The mechanism first. React writes `input.value` after a commit whenever its
value differs from the DOM's. Assigning to `value` sets `selectionStart` and
`selectionEnd` to the end of the string. An untransformed controlled input
never jumps because React's value and the DOM's already agree — the transform is
what creates the difference.

## Hint 2

Record the caret *before* React re-renders, and restore it *after* the DOM has
been written but *before* paint:

```tsx
const caret = useRef<number | null>(null);

function onChange(e: React.ChangeEvent<HTMLInputElement>) {
  caret.current = e.target.selectionStart;
  setValue(normalise(e.target.value));
}

useLayoutEffect(() => {
  if (caret.current !== null) {
    ref.current?.setSelectionRange(caret.current, caret.current);
    caret.current = null;
  }
});
```

`useLayoutEffect`, not `useEffect`: with the latter the jump is visible for a
frame.

## Hint 3

The dropped-character case needs the offset adjusted. The caret position the
browser reported assumes the character was inserted; if your normaliser removed
it, the correct position is one less. Compute it from the lengths:

```tsx
const removed = e.target.value.length - normalised.length;
caret.current = (e.target.selectionStart ?? 0) - removed;
```

For a transform that *inserts* characters — spaces in a card number — the same
arithmetic works with the sign the other way, though a robust version counts
inserted separators before the caret rather than trusting the total.

references.solution.tsx:
// v3rb05_form_state_location / ex1 - reference solution.
import { useId, useLayoutEffect, useRef, useState, type JSX } from "react";

const normalise = (raw: string) => raw.toUpperCase().replace(/[^A-Z0-9]/g, "");

/**
 * The version most codebases ship. It works perfectly while you type at the
 * end of the field, which is the only way its author ever tested it.
 */
export function NaiveCode({ onChange }: { onChange?: (v: string) => void }): JSX.Element {
  const id = useId();
  const [value, setValue] = useState("");

  return (
    <>
      <label htmlFor={id}>Code</label>
      <input
        id={id}
        value={value}
        onChange={(event) => {
          const next = normalise(event.target.value);
          setValue(next);
          onChange?.(next);
        }}
      />
    </>
  );
}

export function SteadyCode({ onChange }: { onChange?: (v: string) => void }): JSX.Element {
  const id = useId();
  const ref = useRef<HTMLInputElement>(null);
  const caret = useRef<number | null>(null);
  const [value, setValue] = useState("");

  // React writes input.value after the commit whenever its value differs from
  // the DOM's, and assigning to value collapses the selection to the end. An
  // untransformed input never jumps because the two already agree; the
  // transform is what creates the difference.
  useLayoutEffect(() => {
    // useLayoutEffect, not useEffect: with the latter the jump is painted for
    // one frame before being corrected.
    if (caret.current === null) return;
    ref.current?.setSelectionRange(caret.current, caret.current);
    // Cleared so an unrelated parent re-render cannot yank the caret back to a
    // stale position.
    caret.current = null;
  });

  return (
    <>
      <label htmlFor={id}>Code</label>
      <input
        id={id}
        ref={ref}
        value={value}
        onChange={(event) => {
          const raw = event.target.value;
          const next = normalise(raw);
          // The reported position assumes every typed character survived. If
          // the normaliser dropped some, the caret belongs that much earlier.
          const removed = raw.length - next.length;
          caret.current = Math.max(0, (event.target.selectionStart ?? next.length) - removed);
          setValue(next);
          onChange?.(next);
        }}
      />
    </>
  );
}

