// v3rb05_form_state_location / ex2 - reference solution.
import { useId, type JSX } from "react";

export type Signup = {
  email: string;
  plan: string;
  interests: string[];
  newsletter: boolean;
  referrer: string | null;
};

/**
 * The boundary where DOM strings become domain types. Pure, testable without
 * rendering anything, and the single place parsing lives.
 */
export function readSignup(form: HTMLFormElement): Signup {
  const data = new FormData(form);

  const referrer = String(data.get("referrer") ?? "").trim();

  return {
    email: String(data.get("email") ?? ""),
    plan: String(data.get("plan") ?? ""),
    // get() returns only the first value and Object.fromEntries keeps only the
    // last: a multiple select needs getAll.
    interests: data.getAll("interests").map(String),
    // An unchecked checkbox is ABSENT from FormData, not false. has() says
    // that out loud and survives a checkbox with an explicit empty value.
    newsletter: data.has("newsletter"),
    referrer: referrer === "" ? null : referrer,
  };
}

export function SignupForm({ onSubmit }: { onSubmit: (data: Signup) => void }): JSX.Element {
  const emailId = useId();
  const planId = useId();
  const interestsId = useId();
  const newsletterId = useId();
  const referrerId = useId();

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit(readSignup(event.currentTarget));
      }}
    >
      <label htmlFor={emailId}>Email</label>
      {/* Every field needs a name: FormData walks named controls, and a field
          without one is simply invisible to it. */}
      <input id={emailId} name="email" defaultValue="" />

      <label htmlFor={planId}>Plan</label>
      <select id={planId} name="plan" defaultValue="free">
        <option value="free">Free</option>
        <option value="pro">Pro</option>
      </select>

      <label htmlFor={interestsId}>Interests</label>
      <select id={interestsId} name="interests" multiple defaultValue={[]}>
        <option value="code">Code</option>
        <option value="design">Design</option>
        <option value="ops">Ops</option>
      </select>

      <label htmlFor={newsletterId}>Newsletter</label>
      <input id={newsletterId} name="newsletter" type="checkbox" defaultChecked={false} />

      <label htmlFor={referrerId}>Referrer</label>
      <input id={referrerId} name="referrer" />

      <button type="submit">Sign up</button>
    </form>
  );
}

// v3rb05_form_state_location / ex3 - reference solution.
import { useId, useState, type JSX } from "react";

export type ProfileRecord = { name?: string; bio?: string | null; age?: number };

/**
 * Reproduced on purpose. React decides per render whether an input is
 * controlled by whether `value` is undefined; `{}` makes these uncontrolled,
 * and the next render with real data makes them controlled - which is exactly
 * what React warns about, because the field's behaviour changed underneath
 * the user.
 */
export function BrokenProfile({ record }: { record: ProfileRecord }): JSX.Element {
  return (
    <div>
      <input aria-label="Name" value={record.name} readOnly />
      <input aria-label="Bio" value={record.bio as string} readOnly />
      <input aria-label="Age" value={record.age as unknown as string} readOnly />
    </div>
  );
}

/**
 * One conversion, at the edge where the server's JSON becomes form values.
 * Servers omit fields, send null for "not set", and send numbers for numeric
 * columns - all three are things an input cannot use as a value.
 */
export function toFormValues(record: ProfileRecord): {
  name: string;
  bio: string;
  age: string;
} {
  return {
    name: record.name ?? "",
    bio: record.bio ?? "",
    // ?? and not ||: age 0 is a real age, and `record.age || ""` would blank
    // it. Same nullish-versus-falsy distinction as the stray zero in
    // conditional rendering, wearing a different costume.
    age: record.age === undefined || record.age === null ? "" : String(record.age),
  };
}

/** The inverse. Write it in the same file, always - forms that skip it send
 *  age: "31" and find out in production. */
export function fromFormValues(values: {
  name: string;
  bio: string;
  age: string;
}): ProfileRecord {
  return {
    name: values.name,
    bio: values.bio.trim() === "" ? null : values.bio,
    age: values.age.trim() === "" ? undefined : Number(values.age),
  };
}

export function Profile({ record }: { record: ProfileRecord }): JSX.Element {
  const nameId = useId();
  const bioId = useId();
  const ageId = useId();

  // Seeded once from the normalised record, so every value is a string from
  // the first render onwards and no input ever changes ownership.
  const [values, setValues] = useState(() => toFormValues(record));

  const set = (field: keyof typeof values) => (event: { target: { value: string } }) =>
    setValues((prev) => ({ ...prev, [field]: event.target.value }));

  return (
    <div>
      <label htmlFor={nameId}>Name</label>
      <input id={nameId} value={values.name} onChange={set("name")} />

      <label htmlFor={bioId}>Bio</label>
      <input id={bioId} value={values.bio} onChange={set("bio")} />

      <label htmlFor={ageId}>Age</label>
      <input id={ageId} value={values.age} onChange={set("age")} />
    </div>
  );
}

