// v3rb05_form_state_location / ex4 - reference solution.
import {
  forwardRef,
  memo,
  useId,
  useImperativeHandle,
  useState,
  type JSX,
} from "react";

export type NoteHandle = { getValue: () => string };

/**
 * Controlled INSIDE. The parent never sees a keystroke, so a keystroke
 * re-renders exactly one component. This is React Hook Form's architecture in
 * miniature.
 */
export const NoteField = forwardRef<NoteHandle, { label: string; defaultValue?: string }>(
  function NoteField({ label, defaultValue = "" }, ref) {
    const id = useId();
    const [value, setValue] = useState(defaultValue);

    // [value] is load-bearing: with an empty array the handle closes over the
    // first render's value forever and getValue() returns "" - silently, with
    // no warning.
    useImperativeHandle(ref, () => ({ getValue: () => value }), [value]);

    return (
      <>
        <label htmlFor={id}>{label}</label>
        <input id={id} value={value} onChange={(event) => setValue(event.target.value)} />
      </>
    );
  },
);

export const ExpensiveField = memo(function ExpensiveField({
  label,
  value,
  onChange,
  renderCount,
}: {
  label: string;
  value: string;
  onChange: (next: string) => void;
  renderCount: { current: number };
}): JSX.Element {
  renderCount.current += 1;
  const id = useId();

  return (
    <>
      <label htmlFor={id}>{label}</label>
      <select id={id} value={value} onChange={(event) => onChange(event.target.value)}>
        <option value="low">low</option>
        <option value="high">high</option>
      </select>
    </>
  );
});

export function OrderForm({
  onSubmit,
  renderCount,
}: {
  onSubmit: (data: { note: string; priority: string }) => void;
  renderCount: { current: number };
}): JSX.Element {
  const noteRef = useState(() => ({ current: null as NoteHandle | null }))[0];
  const [priority, setPriority] = useState("low");

  // A stable handler identity, or memo on the child compares a new function
  // every render and does nothing - the usual reason "memo doesn't work".
  const [onPriorityChange] = useState(() => (next: string) => setPriority(next));

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        onSubmit({ note: noteRef.current?.getValue() ?? "", priority });
      }}
    >
      <NoteField
        label="Note"
        ref={(handle) => {
          noteRef.current = handle;
        }}
      />
      <ExpensiveField
        label="Priority"
        value={priority}
        onChange={onPriorityChange}
        renderCount={renderCount}
      />
      <button type="submit">Submit</button>
    </form>
  );
}

// v3rb05_form_state_location / ex5 - reference solution.
import { useEffect, useId, useState, type JSX } from "react";

type Record = { id: string; title: string; notes: string };

/**
 * The version under diagnosis. Two failures, and the second is worse.
 *
 * 1. It resets the fields its author knew about. `expanded` was added later by
 *    somebody else and nothing connects the two - every piece of state added
 *    after this effect is written is state it silently forgets.
 * 2. Effects run AFTER the commit, so there is a painted frame showing the new
 *    record with the old values. One frame on a fast machine; a screenshot in
 *    a bug report from a user clicking quickly through a list.
 */
export function EffectSyncedForm({ record }: { record: Record }): JSX.Element {
  const titleId = useId();
  const notesId = useId();

  const [title, setTitle] = useState(record.title);
  const [notes, setNotes] = useState(record.notes);
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    setTitle(record.title);
    setNotes(record.notes);
  }, [record]);

  return (
    <div>
      <label htmlFor={titleId}>Title</label>
      <input id={titleId} value={title} onChange={(e) => setTitle(e.target.value)} />

      <label htmlFor={notesId}>Notes</label>
      <input id={notesId} value={notes} onChange={(e) => setNotes(e.target.value)} />

      <button type="button" onClick={() => setExpanded((prev) => !prev)}>
        Toggle details
      </button>
      <p data-testid="expanded">{String(expanded)}</p>
    </div>
  );
}

/** Knows nothing about resetting. That is the point. */
export function EditForm({ record }: { record: Record }): JSX.Element {
  const titleId = useId();
  const notesId = useId();

  const [title, setTitle] = useState(record.title);
  const [notes, setNotes] = useState(record.notes);
  const [expanded, setExpanded] = useState(false);

  return (
    <div>
      <label htmlFor={titleId}>Title</label>
      <input id={titleId} value={title} onChange={(e) => setTitle(e.target.value)} />

      <label htmlFor={notesId}>Notes</label>
      <input id={notesId} value={notes} onChange={(e) => setNotes(e.target.value)} />

      <button type="button" onClick={() => setExpanded((prev) => !prev)}>
        Toggle details
      </button>
      <p data-testid="expanded">{String(expanded)}</p>
    </div>
  );
}

export function EditPanel({ record }: { record: Record }): JSX.Element {
  // State belongs to a position in the tree, identified by type and key. A new
  // key is a new thing, so React discards the whole instance - including state
  // this file never had to enumerate.
  //
  // The cost, which is real: remounting also discards DOM state - focus,
  // selection, scroll. Key on the thing whose change means "different
  // subject", never on an object identity that a refetch might replace.
  return <EditForm key={record.id} record={record} />;
}

