// v3rb05_form_state_location / ex6 - reference solution.
import { useCallback, useId, useState, type JSX } from "react";

export function useDraft<T extends Record<string, string>>(
  initial: T,
): {
  values: T;
  set: (field: keyof T, value: string) => void;
  reset: () => void;
  commit: () => void;
  dirtyFields: (keyof T)[];
  isDirty: boolean;
} {
  // The baseline is state rather than a prop so a successful save can move it
  // without a remount - which keeps focus and scroll position, unlike a
  // key-based reset.
  const [baseline, setBaseline] = useState(initial);
  const [values, setValues] = useState(initial);

  const set = useCallback((field: keyof T, value: string) => {
    setValues((prev) => ({ ...prev, [field]: value }));
  }, []);

  const reset = useCallback(() => setValues(baseline), [baseline]);
  const commit = useCallback(() => setBaseline(values), [values]);

  // Derived, never stored. The stored version fails on a keystroke followed by
  // a backspace: nothing tells it the field came home, so the button claims
  // unsaved changes for a form identical to how it started.
  //
  // Keys come from the baseline so the order is stable and an extra key in
  // `values` cannot masquerade as a dirty field.
  const dirtyFields = (Object.keys(baseline) as (keyof T)[]).filter(
    (field) => values[field] !== baseline[field],
  );

  return { values, set, reset, commit, dirtyFields, isDirty: dirtyFields.length > 0 };
}

export function SettingsForm({
  initial,
  save,
}: {
  initial: { displayName: string; email: string };
  save: (values: { displayName: string; email: string }) => Promise<void>;
}): JSX.Element {
  const nameId = useId();
  const emailId = useId();

  const { values, set, reset, commit, dirtyFields, isDirty } = useDraft(initial);
  const [saving, setSaving] = useState(false);

  const onSave = async () => {
    setSaving(true);
    try {
      await save(values);
      commit();
    } finally {
      setSaving(false);
    }
  };

  return (
    <div>
      <label htmlFor={nameId}>Display name</label>
      <input
        id={nameId}
        value={values.displayName}
        onChange={(event) => set("displayName", event.target.value)}
      />

      <label htmlFor={emailId}>Email</label>
      <input
        id={emailId}
        value={values.email}
        onChange={(event) => set("email", event.target.value)}
      />

      {/* Derived too: there is no `canSave` state to drift. */}
      <button type="button" disabled={!isDirty || saving} onClick={() => void onSave()}>
        Save
      </button>
      <button type="button" disabled={!isDirty} onClick={reset}>
        Discard
      </button>

      <p data-testid="dirty">{dirtyFields.join(", ")}</p>
    </div>
  );
}

