// v3rb05_form_state_location / ex7 - reference solution.
import { useId, useState, type JSX } from "react";

const COMPLETE = /^-?\d+(\.\d+)?$/;
const INCOMPLETE = /^-?(\d+\.?|\.)?$/; // "", "-", ".", "-.", "1.", "-1."

export function useNumberField(
  initial: number | null,
  {
    min = -Infinity,
    max = Infinity,
    allowDecimal = true,
  }: { min?: number; max?: number; allowDecimal?: boolean } = {},
): {
  raw: string;
  setRaw: (next: string) => void;
  value: number | null;
  problem: "empty" | "incomplete" | "not-a-number" | "out-of-range" | null;
  commit: () => void;
} {
  // The STRING is the state. Storing the parsed number and rendering it back
  // means "1." collapses to "1" and deletes the character the user just typed.
  const [raw, setRawState] = useState(initial === null ? "" : String(initial));

  const setRaw = (next: string) => {
    // Only characters that can never appear are stripped. Everything the user
    // might be part-way through typing survives.
    const allowed = allowDecimal ? /[^0-9.\-]/g : /[^0-9\-]/g;
    let cleaned = next.replace(allowed, "");
    cleaned = cleaned.replace(/(?!^)-/g, ""); // one leading minus only
    if (allowDecimal) {
      const first = cleaned.indexOf(".");
      if (first !== -1) {
        cleaned = cleaned.slice(0, first + 1) + cleaned.slice(first + 1).replace(/\./g, "");
      }
    }
    setRawState(cleaned);
  };

  const complete = COMPLETE.test(raw);
  // Number("") is 0 and Number(" ") is 0, which is how an empty field quietly
  // writes a zero into a nullable column. Parse only what has been checked.
  const value = complete ? Number(raw) : null;

  const problem: "empty" | "incomplete" | "not-a-number" | "out-of-range" | null =
    raw === ""
      ? "empty"
      : complete
        ? value !== null && (value < min || value > max)
          ? "out-of-range"
          : null
        : // "not a number YET" is different from "will never be a number".
          // Telling a user halfway through typing 1.5 that it is invalid is
          // noise; telling somebody who typed "abc" is help.
          INCOMPLETE.test(raw)
          ? "incomplete"
          : "not-a-number";

  const commit = () => {
    if (value === null) return;
    // Normalise at the boundary, where the caret is leaving anyway. Doing this
    // on change would delete the leading zeros as the user typed them.
    setRawState(String(value));
  };

  return { raw, setRaw, value, problem, commit };
}

export function PriceField({
  initial,
  onCommit,
}: {
  initial: number | null;
  onCommit: (value: number | null) => void;
}): JSX.Element {
  const id = useId();
  const field = useNumberField(initial, { min: 0 });

  return (
    <div>
      <label htmlFor={id}>Price</label>
      <input
        id={id}
        // type="text" with inputMode: type="number" reports "" for anything
        // the browser dislikes, so a half-typed exponent is unrecoverable.
        type="text"
        inputMode="decimal"
        value={field.raw}
        onChange={(event) => field.setRaw(event.target.value)}
        onBlur={() => {
          field.commit();
          onCommit(field.value);
        }}
      />
      {field.problem !== null && field.problem !== "incomplete" ? (
        <p role="status">{field.problem}</p>
      ) : null}
    </div>
  );
}

