// v3rb05_form_state_location / ex8 - reference solution.
import { useCallback, useState, type ChangeEvent } from "react";

export type FieldValue = string | boolean | string[] | FileList | null;

type Control = HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;

export function readControl(el: Control): FieldValue {
  if (el instanceof HTMLSelectElement) {
    // get() on a multiple select returns the first value only; the DOM's own
    // selectedOptions is the honest source.
    return el.multiple ? Array.from(el.selectedOptions, (option) => option.value) : el.value;
  }

  if (el instanceof HTMLInputElement) {
    // A checkbox's `value` is the string "on" by default and stays "on"
    // whether it is checked or not - reading it is the single most common
    // form bug in React codebases.
    if (el.type === "checkbox") return el.checked;

    // An unchecked radio must not answer for its group.
    if (el.type === "radio") return el.checked ? el.value : null;

    // File inputs cannot be controlled at all: setting `value` is a security
    // restriction, so they are always read, never written.
    if (el.type === "file") return el.files;
  }

  return el.value;
}

export function useMiniForm(initial: Record<string, FieldValue>): {
  values: Record<string, FieldValue>;
  register: (name: string) => {
    name: string;
    onChange: (event: ChangeEvent<Control>) => void;
  };
} {
  const [values, setValues] = useState(initial);

  const register = useCallback(
    (name: string) => ({
      name,
      onChange: (event: ChangeEvent<Control>) => {
        const next = readControl(event.target);

        // A null from an unchecked radio is "no opinion", not "clear the
        // group" - a programmatic click or a form reset can deliver one.
        if (next === null && event.target instanceof HTMLInputElement && event.target.type === "radio") {
          return;
        }

        // Read the name off the control rather than the closure: a misspelled
        // name on one member of a radio group then shows up as a stray key
        // instead of silently splitting the group.
        const key = event.target.name || name;
        setValues((prev) => ({ ...prev, [key]: next }));
      },
    }),
    [],
  );

  return { values, register };
}

