  notes: string;
};

const COMPLETE_NUMBER = /^\d+(\.\d+)?$/;

export function ShipmentForm({
  regionsFor,
  submit,
  initial,
}: {
  regionsFor: (country: string) => string[];
  submit: (draft: ShipmentDraft) => Promise<void>;
  initial?: Partial<ShipmentDraft>;
}): JSX.Element {
  // One generation counter, one key: discards the controlled state AND
  // remounts the uncontrolled inputs so their defaultValues apply again. The
  // only mechanism that resets both kinds at once.
  const [generation, setGeneration] = useState(0);

  return (
    <div>
      <ShipmentFields
        key={generation}
        regionsFor={regionsFor}
        submit={submit}
        initial={initial}
      />
      <button type="button" onClick={() => setGeneration((g) => g + 1)}>
        Reset
      </button>
    </div>
  );
}

function ShipmentFields({
  regionsFor,
  submit,
  initial,
}: {
  regionsFor: (country: string) => string[];
  submit: (draft: ShipmentDraft) => Promise<void>;
  initial?: Partial<ShipmentDraft>;
}): JSX.Element {
  const recipientId = useId();
  const countryId = useId();
  const regionId = useId();
  const weightId = useId();
  const expressId = useId();
  const notesId = useId();

  // Resolved once, at the top: sprinkling ?? at each defaultValue scatters the
  // knowledge of what the defaults are across six places.
  const countries = ["UK", "DE", "US"];
  const defaults: ShipmentDraft = {
    recipient: initial?.recipient ?? "",
    country: initial?.country ?? countries[0],
    region: initial?.region ?? regionsFor(initial?.country ?? countries[0])[0] ?? "",
    weightKg: initial?.weightKg ?? null,
    express: initial?.express ?? false,
    notes: initial?.notes ?? "",
  };

  // Controlled, because the region select depends on it during typing.
  const [country, setCountry] = useState(defaults.country);
  const [region, setRegion] = useState(defaults.region);

  // Controlled as a STRING: "1." must survive being typed.
  const [weightRaw, setWeightRaw] = useState(
    defaults.weightKg === null ? "" : String(defaults.weightKg),
  );

  const [error, setError] = useState<string | null>(null);

  const regions = regionsFor(country);
  const weight = COMPLETE_NUMBER.test(weightRaw) ? Number(weightRaw) : null;

  const onCountryChange = (next: string) => {
    // Both values computed from the new country in one handler: reading a
    // memoised region list from the previous render would use the old country.
    setCountry(next);
    setRegion(regionsFor(next)[0] ?? "");
  };

  const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const data = new FormData(event.currentTarget);
    const recipient = String(data.get("recipient") ?? "").trim();

    // Not a disabled button: a disabled control tells a screen-reader user
    // nothing about why they cannot proceed. Let them submit, then explain.
    if (recipient === "") {
      setError("Recipient is required");
      return;
    }

    setError(null);
    await submit({
      recipient,
      country,
      region,
      weightKg: weight,
      express: data.has("express"),
      notes: String(data.get("notes") ?? ""),
    });
  };

  return (
    <form onSubmit={(event) => void onSubmit(event)}>
      {/* Nothing needs these during typing, so nothing pays for them. */}
      <label htmlFor={recipientId}>Recipient</label>
      <input id={recipientId} name="recipient" defaultValue={defaults.recipient} />

      <label htmlFor={countryId}>Country</label>
      <select
        id={countryId}
        name="country"
        value={country}
        onChange={(event) => onCountryChange(event.target.value)}
      >
        {countries.map((code) => (
          <option key={code} value={code}>
            {code}
          </option>
        ))}
      </select>

      <label htmlFor={regionId}>Region</label>
      <select
        id={regionId}
        name="region"
        value={region}
        onChange={(event) => setRegion(event.target.value)}
      >
        {regions.map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>

      <label htmlFor={weightId}>Weight (kg)</label>
      <input
        id={weightId}
        type="text"
        inputMode="decimal"
        value={weightRaw}
        onChange={(event) => setWeightRaw(event.target.value.replace(/[^0-9.]/g, ""))}
      />
      {weight !== null && weight > 70 ? (
        <p role="status">Over 70kg needs freight</p>
      ) : null}

      <label htmlFor={expressId}>Express</label>
      <input
        id={expressId}
        name="express"
        type="checkbox"
        defaultChecked={defaults.express}
      />

      <label htmlFor={notesId}>Notes</label>
      <textarea id={notesId} name="notes" defaultValue={defaults.notes} />

      <button type="submit">Ship</button>
      {error !== null ? <p role="alert">{error}</p> : null}
    </form>
  );
}

// v3rb05_form_state_location / review1 - reference solution.
import { useEffect, useRef, useState, type JSX } from "react";

export type WizardData = Record<string, string>;

type Step = { id: string; title: string; fields: string[] };

export function Wizard({
  steps,
  onFinish,
}: {
  steps: Step[];
  onFinish: (data: WizardData) => void;
}): JSX.Element {
  // Answers live above; fields live below; the transition is where they meet.
  const [answers, setAnswers] = useState<WizardData>({});
  const [index, setIndex] = useState(0);
  const formRef = useRef<HTMLFormElement>(null);

  const step = steps[index];
  const isLast = index === steps.length - 1;

  const readCurrentStep = (): WizardData => {
    const form = formRef.current;
    if (!form) return {};
    const data = new FormData(form);
    const collected: WizardData = {};
    for (const field of step.fields) {
      collected[field] = String(data.get(field) ?? "");
    }
    return collected;
  };

  // BOTH directions read. Wiring the read only into Next is why "going back
  // loses my answers" is the archetypal wizard bug.
  const move = (delta: number) => {
    const merged = { ...answers, ...readCurrentStep() };
    setAnswers(merged);

    if (delta > 0 && isLast) {
      onFinish(merged);
      return;
    }
    setIndex((prev) => Math.min(steps.length - 1, Math.max(0, prev + delta)));
  };

  useEffect(() => {
    // Without this, focus falls to <body> on every transition and a keyboard
    // user tabs from the top of the document to reach each step's first field.
    formRef.current?.querySelector("input")?.focus();
  }, [index]);

  return (
    <div>
      <p data-testid="progress">
        Step {index + 1} of {steps.length}
      </p>

      {/* The key is essential rather than tidy: without it the same input DOM
          nodes are reused at the same positions, and defaultValue - read once
          at mount - never reapplies, so step two shows step one's text. */}
      <form key={step.id} ref={formRef} onSubmit={(event) => event.preventDefault()}>
        <h2>{step.title}</h2>
        {step.fields.map((field) => (
          <div key={field}>
            <label htmlFor={`${step.id}-${field}`}>{field}</label>
            <input
              id={`${step.id}-${field}`}
              name={field}
              // The browser does the remembering; the wizard only accumulates.
              defaultValue={answers[field] ?? ""}
            />
          </div>
        ))}
      </form>

      <button type="button" disabled={index === 0} onClick={() => move(-1)}>
        Back
      </button>
      <button type="button" onClick={() => move(1)}>
        {isLast ? "Finish" : "Next"}
      </button>
    </div>
  );
}

