// v3rb06_validation_a11y / ex1 - reference solution.
import { useId, useState, type JSX } from "react";

export type Values = { email: string; password: string };
export type Errors = Partial<Record<keyof Values, string>>;

/**
 * Pure. No React, so it can be tested exhaustively without rendering and run
 * on the server, which is the only way the two stay in agreement.
 */
export function validate(values: Values): Errors {
  const errors: Errors = {};

  if (values.email.trim() === "") errors.email = "Enter your email address";
  else if (!values.email.includes("@")) errors.email = "Enter a valid email address";

  if (values.password.length < 12) errors.password = "Use at least 12 characters";

  return errors;
}

export function LoginForm({ onSubmit }: { onSubmit: (v: Values) => void }): JSX.Element {
  const emailId = useId();
  const passwordId = useId();

  const [values, setValues] = useState<Values>({ email: "", password: "" });
  const [touched, setTouched] = useState<Partial<Record<keyof Values, boolean>>>({});

  // Derived every render. Stored errors can disagree with the values they
  // describe the moment somebody adds a second way to change a value.
  const errors = validate(values);

  // The single indirection that implements both halves of the rule. Untouched:
  // silent, however wrong. Touched: recomputed on every keystroke, so the
  // message clears the instant it stops being true - no extra code.
  const show = (field: keyof Values) => (touched[field] ? errors[field] : undefined);

  const set = (field: keyof Values) => (event: { target: { value: string } }) =>
    setValues((prev) => ({ ...prev, [field]: event.target.value }));

  const blur = (field: keyof Values) => () =>
    setTouched((prev) => ({ ...prev, [field]: true }));

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        // Submitting touches everything at once.
        setTouched({ email: true, password: true });
        if (Object.keys(errors).length > 0) return;
        onSubmit(values);
      }}
    >
      <label htmlFor={emailId}>Email</label>
      <input
        id={emailId}
        value={values.email}
        onChange={set("email")}
        onBlur={blur("email")}
      />
      {show("email") ? <p>{show("email")}</p> : null}

      <label htmlFor={passwordId}>Password</label>
      <input
        id={passwordId}
        type="password"
        value={values.password}
        onChange={set("password")}
        onBlur={blur("password")}
      />
      {show("password") ? <p>{show("password")}</p> : null}

      {/* Never disabled: a disabled button leaves the tab order, so a keyboard
          user never reaches it and never learns why they cannot proceed. */}
      <button type="submit">Sign in</button>
    </form>
  );
}

