// v3rb06_validation_a11y / ex2 - reference solution.
import { useId, type JSX } from "react";

export function Field({
  label,
  hint,
  error,
  value,
  onChange,
  onBlur,
  type = "text",
}: {
  label: string;
  hint?: string;
  error?: string;
  value: string;
  onChange: (next: string) => void;
  onBlur?: () => void;
  type?: string;
}): JSX.Element {
  // One id per instance, everything else derived from it. Never build ids from
  // the label text: two fields labelled "Amount" in different sections would
  // collide silently.
  const id = useId();
  const hintId = `${id}-hint`;
  const errorId = `${id}-error`;

  // Space separated, hint first, so the description reads as guidance then
  // problem. `|| undefined` because aria-describedby="" is an empty reference
  // rather than an absent one.
  const describedBy =
    [hint ? hintId : null, error ? errorId : null].filter(Boolean).join(" ") || undefined;

  return (
    <div>
      <label htmlFor={id}>{label}</label>

      {hint ? <p id={hintId}>{hint}</p> : null}

      <input
        id={id}
        type={type}
        value={value}
        onChange={(event) => onChange(event.target.value)}
        onBlur={onBlur}
        // Absent rather than "false" when valid: the two are computed
        // identically, and a DOM full of aria-invalid="false" hides the real
        // ones during an audit.
        aria-invalid={error ? "true" : undefined}
        aria-describedby={describedBy}
      />

      {/* The element exists only when there is an error, which is why the
          describedby reference is conditional too - a dangling reference is
          worse than none. */}
      {error ? <p id={errorId}>{error}</p> : null}
    </div>
  );
}

