// v3rb06_validation_a11y / ex3 - reference solution.
import { useEffect, useId, useRef, useState, type JSX } from "react";

export function ApplicationForm({
  fields,
  validate,
  onSubmit,
}: {
  fields: { name: string; label: string }[];
  validate: (values: Record<string, string>) => Record<string, string>;
  onSubmit: (values: Record<string, string>) => void;
}): JSX.Element {
  const base = useId();
  const idFor = (name: string) => `${base}-${name}`;

  const [values, setValues] = useState<Record<string, string>>({});
  const [errors, setErrors] = useState<Record<string, string>>({});
  // A counter, not a boolean: two identical failures must both move focus, and
  // an effect keyed on the errors themselves would not re-run when nothing
  // changed.
  const [attempt, setAttempt] = useState(0);

  const summaryRef = useRef<HTMLDivElement>(null);

  // Built from `fields`, not from Object.entries(errors): object-key order is
  // whatever the validator happened to assign in, so "the first error" would
  // mean something different to the user and to the code.
  const errorList = fields
    .filter((field) => errors[field.name])
    .map((field) => ({ ...field, message: errors[field.name] }));

  useEffect(() => {
    if (attempt > 0 && errorList.length > 0) summaryRef.current?.focus();
    // Only the attempt counter: this must fire once per submit, whatever the
    // errors are.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attempt]);

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        const next = validate(values);
        setErrors(next);
        setAttempt((prev) => prev + 1);
        if (Object.keys(next).length === 0) onSubmit(values);
      }}
    >
      {errorList.length > 0 ? (
        <div
          ref={summaryRef}
          // Programmatically focusable without joining the tab order. Without
          // it, .focus() on a div silently does nothing.
          tabIndex={-1}
          // Redundant with the focus move in most readers, and the safety net
          // in the ones where focusing does not announce.
          role="alert"
        >
          <h2>There is a problem</h2>
          <ul>
            {errorList.map((error) => (
              <li key={error.name}>
                <a
                  href={`#${idFor(error.name)}`}
                  onClick={(event) => {
                    event.preventDefault();
                    document.getElementById(idFor(error.name))?.focus();
                  }}
                >
                  {error.message}
                </a>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {fields.map((field) => (
        <div key={field.name}>
          <label htmlFor={idFor(field.name)}>{field.label}</label>
          <input
            id={idFor(field.name)}
            value={values[field.name] ?? ""}
            aria-invalid={errors[field.name] ? "true" : undefined}
            onChange={(event) =>
              setValues((prev) => ({ ...prev, [field.name]: event.target.value }))
            }
          />
        </div>
      ))}

      <button type="submit">Submit</button>
    </form>
  );
}

