// v3rb06_validation_a11y / ex4 - reference solution.
import { useId, useState, type JSX } from "react";

/**
 * The platform supplies the engine - eight named booleans, localised and
 * well-tested. We supply the words. setCustomValidity would be the obvious
 * API and is a trap: it makes the control permanently invalid until cleared,
 * and a missed clear produces a form that can never be submitted.
 */
export function messageFor(el: HTMLInputElement): string | null {
  const v = el.validity;
  if (v.valid) return null;

  const label = el.dataset.label ?? el.name;

  // Most specific first: more than one flag can be true, and "you left it
  // blank" is more useful than "that is not an email address".
  if (v.valueMissing) return `${label} is required`;
  if (v.typeMismatch && el.type === "email") {
    return "Enter an email address like name@example.com";
  }
  if (v.rangeUnderflow) return `Must be ${el.min} or more`;
  if (v.rangeOverflow) return `Must be ${el.max} or less`;
  if (v.tooShort) return `Use at least ${el.minLength} characters`;
  if (v.patternMismatch) return "Use letters and numbers only";

  // The browser's own string, localised into the user's language - which our
  // hard-coded English is not. A constraint added to the markup later degrades
  // to something sensible rather than to null.
  return el.validationMessage;
}

export function BookingForm({ onSubmit }: { onSubmit: (data: FormData) => void }): JSX.Element {
  const base = useId();
  const [messages, setMessages] = useState<Record<string, string>>({});

  const idFor = (name: string) => `${base}-${name}`;
  const errorIdFor = (name: string) => `${base}-${name}-error`;

  const aria = (name: string) => ({
    id: idFor(name),
    "aria-invalid": messages[name] ? ("true" as const) : undefined,
    "aria-describedby": messages[name] ? errorIdFor(name) : undefined,
  });

  return (
    <form
      // Turns off the unstylable bubble and the submission blocking, while
      // leaving `validity` fully populated on every control.
      noValidate
      onSubmit={(event) => {
        event.preventDefault();
        const form = event.currentTarget;

        // form.elements includes buttons; the instanceof narrow filters them
        // and gives TypeScript the `validity` property at the same time.
        const controls = Array.from(form.elements).filter(
          (el): el is HTMLInputElement => el instanceof HTMLInputElement,
        );

        const next: Record<string, string> = {};
        for (const control of controls) {
          const message = messageFor(control);
          if (message !== null) next[control.name] = message;
        }

        setMessages(next);
        if (Object.keys(next).length === 0) onSubmit(new FormData(form));
      }}
    >
      <label htmlFor={idFor("email")}>Email</label>
      <input {...aria("email")} name="email" type="email" required data-label="Email" />
      {messages.email ? <p id={errorIdFor("email")}>{messages.email}</p> : null}

      <label htmlFor={idFor("guests")}>Guests</label>
      <input
        {...aria("guests")}
        name="guests"
        type="number"
        min="1"
        max="8"
        required
        data-label="Guests"
      />
      {messages.guests ? <p id={errorIdFor("guests")}>{messages.guests}</p> : null}

      <label htmlFor={idFor("code")}>Code</label>
      <input
        {...aria("code")}
        name="code"
        pattern="[A-Za-z0-9]+"
        minLength={4}
        data-label="Code"
      />
      {messages.code ? <p id={errorIdFor("code")}>{messages.code}</p> : null}

      <button type="submit">Book</button>
    </form>
  );
}

