// v3rb06_validation_a11y / ex5 - reference solution.
import { useEffect, useId, useState, type JSX } from "react";

export type Availability = "idle" | "checking" | "free" | "taken" | "unknown";

export function useAvailability(
  username: string,
  check: (username: string, signal: AbortSignal) => Promise<boolean>,
  { debounceMs = 400, minLength = 3 }: { debounceMs?: number; minLength?: number } = {},
): Availability {
  const [state, setState] = useState<Availability>("idle");

  useEffect(() => {
    if (username.trim().length < minLength) {
      setState("idle");
      return;
    }

    const controller = new AbortController();

    const timer = setTimeout(() => {
      setState("checking");
      check(username, controller.signal).then(
        (free) => {
          if (controller.signal.aborted) return;
          setState(free ? "free" : "taken");
        },
        () => {
          if (controller.signal.aborted) return;
          // "We asked and could not find out" is a different state from "we
          // have not asked", and it is never an error - a network hiccup must
          // not stop somebody signing up.
          setState("unknown");
        },
      );
    }, debounceMs);

    // Both cleanups belong to this run. The debounce reduces requests; only
    // the abort orders the answers, and without it the race becomes
    // intermittent rather than fixed.
    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [username, check, debounceMs, minLength]);

  return state;
}

export function UsernameField({
  check,
  onSubmit,
}: {
  check: (username: string, signal: AbortSignal) => Promise<boolean>;
  onSubmit: (username: string) => void;
}): JSX.Element {
  const id = useId();
  const [username, setUsername] = useState("");
  const availability = useAvailability(username, check);

  const message =
    availability === "checking"
      ? "Checking availability"
      : availability === "free"
        ? `${username} is available`
        : availability === "taken"
          ? `${username} is taken`
          : "";

  return (
    <div>
      <label htmlFor={id}>Username</label>
      <input id={id} value={username} onChange={(e) => setUsername(e.target.value)} />

      {/* Rendered unconditionally: screen readers watch a live region for
          mutations, and a region inserted already containing text may not be
          announced at all. Polite, never assertive - an alert here would talk
          over the user on every keystroke. */}
      <p aria-live="polite">{message}</p>

      {/* Never disabled by availability. This check is a courtesy that saves a
          round trip; the server is the authority. */}
      <button type="button" onClick={() => onSubmit(username)}>
        Create
      </button>
    </div>
  );
}

// v3rb06_validation_a11y / ex6 - reference solution.
import { useId, useState, type JSX } from "react";

export type TripValues = {
  password: string;
  confirm: string;
  start: string;
  end: string;
};

type TripErrors = Partial<Record<keyof TripValues, string>>;

export function validateTrip(values: TripValues): TripErrors {
  const errors: TripErrors = {};

  if (values.password.length < 12) {
    errors.password = "Use at least 12 characters";
  } else if (values.confirm !== values.password) {
    // The else is doing real work: while the password itself is invalid,
    // "does not match" is noise about a value that is about to change.
    //
    // And the error goes on `confirm`, not on both. Attach a cross-field error
    // to the input the user will change to fix it.
    errors.confirm = "Passwords do not match";
  }

  if (values.start === "") errors.start = "Enter a start date";
  if (values.end === "") errors.end = "Enter an end date";

  if (!errors.start && !errors.end && values.end < values.start) {
    // String comparison is correct here only because the format is yyyy-mm-dd,
    // which sorts lexicographically in the same order as chronologically.
    // Change the format and this silently becomes wrong.
    errors.end = "End date must be after the start date";
  }

  return errors;
}

export function TripForm({ onSubmit }: { onSubmit: (v: TripValues) => void }): JSX.Element {
  const base = useId();
  const [values, setValues] = useState<TripValues>({
    password: "",
    confirm: "",
    start: "",
    end: "",
  });
  const [touched, setTouched] = useState<Partial<Record<keyof TripValues, boolean>>>({});

  // Derived, so editing `password` recomputes `confirm`'s error immediately.
  // With stored errors, "clears when either field changes" would need explicit
  // cross-clearing - which is the bug this design prevents.
  const errors = validateTrip(values);

  const field = (name: keyof TripValues, label: string, type = "text") => {
    const id = `${base}-${name}`;
    const errorId = `${id}-error`;
    const error = touched[name] ? errors[name] : undefined;

    return (
      <div>
        <label htmlFor={id}>{label}</label>
        <input
          id={id}
          type={type}
          value={values[name]}
          aria-invalid={error ? "true" : undefined}
          aria-describedby={error ? errorId : undefined}
          onChange={(event) =>
            setValues((prev) => ({ ...prev, [name]: event.target.value }))
          }
          onBlur={() => setTouched((prev) => ({ ...prev, [name]: true }))}
        />
        {error ? <p id={errorId}>{error}</p> : null}
      </div>
    );
  };

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        setTouched({ password: true, confirm: true, start: true, end: true });
        if (Object.keys(errors).length > 0) return;
        onSubmit(values);
      }}
    >
      {field("password", "Password", "password")}
      {field("confirm", "Confirm password", "password")}
      {field("start", "Start date", "date")}
      {field("end", "End date", "date")}
      <button type="submit">Save</button>
    </form>
  );
}

