// v3rb06_validation_a11y / ex7 - reference solution.

export type Rule<T> = { test: (value: string, all: T) => boolean; message: string };

export type Schema<T> = {
  field: keyof T & string;
  label: string;
  rules: Rule<T>[];
}[];

export type Issue = { field: string; label: string; message: string };

export const required = (label: string): Rule<Record<string, string>> => ({
  test: (value) => value.trim() !== "",
  message: `${label} is required`,
});

export const minLength = (n: number): Rule<Record<string, string>> => ({
  test: (value) => value.length >= n,
  message: `Use at least ${n} characters`,
});

export const matches = (
  pattern: RegExp,
  message: string,
): Rule<Record<string, string>> => ({
  test: (value) => pattern.test(value),
  message,
});

export const sameAs = <T extends Record<string, string>>(
  other: keyof T & string,
  message: string,
): Rule<T> => ({
  test: (value, all) => value === all[other],
  message,
});

function safeTest<T>(rule: Rule<T>, value: string, all: T): boolean {
  try {
    return rule.test(value, all);
  } catch {
    // A rule reading `all.otherField.trim()` throws when that key is absent.
    // Without this guard, one missing key takes down the whole validation and
    // the form can neither submit nor explain why.
    return false;
  }
}

export function validateSchema<T extends Record<string, string>>(
  values: T,
  schema: Schema<T>,
): { byField: Record<string, string>; issues: Issue[] } {
  const byField: Record<string, string> = {};
  const issues: Issue[] = [];

  // Iterating the SCHEMA is what makes `issues` come back in form order,
  // regardless of how the values object's keys happen to be ordered. An object
  // schema would give insertion order - whatever the author typed - and it
  // drifts as fields are added.
  for (const entry of schema) {
    const value = values[entry.field] ?? "";

    // First failure wins: a field with three simultaneous complaints is a
    // field nobody reads, and one message fits beside the input.
    const failed = entry.rules.find((rule) => !safeTest(rule, value, values));
    if (!failed) continue;

    byField[entry.field] = failed.message;
    issues.push({ field: entry.field, label: entry.label, message: failed.message });
  }

  return { byField, issues };
}

