// v3rb06_validation_a11y / ex8 - reference solution.
import { useEffect, useId, useRef, useState, type JSX } from "react";

export class ValidationFailed extends Error {
  readonly fieldErrors: Record<string, string>;
  readonly formError?: string;

  constructor(fieldErrors: Record<string, string>, formError?: string) {
    super(formError ?? "Validation failed");
    this.name = "ValidationFailed";
    this.fieldErrors = fieldErrors;
    this.formError = formError;
  }
}

export function mapServerErrors(
  error: unknown,
  knownFields: readonly string[],
): { byField: Record<string, string>; formError: string | null } {
  if (!(error instanceof ValidationFailed)) {
    return {
      byField: {},
      formError: error instanceof Error ? error.message : String(error),
    };
  }

  const byField: Record<string, string> = {};
  const unknown: string[] = [];

  for (const [field, message] of Object.entries(error.fieldErrors)) {
    // A server that validates a field this form does not render must not
    // produce an error that goes nowhere: the user would see a save fail with
    // no explanation at all.
    if (knownFields.includes(field)) byField[field] = message;
    else unknown.push(`${field}: ${message}`);
  }

  const parts = [error.formError, unknown.join("; ")].filter(
    (part): part is string => Boolean(part),
  );

  const formError =
    parts.length > 0
      ? parts.join("; ")
      : Object.keys(byField).length > 0
        ? null
        : "Could not save your changes";

  return { byField, formError };
}

export function AccountForm({
  fields,
  save,
}: {
  fields: { name: string; label: string }[];
  save: (values: Record<string, string>) => Promise<void>;
}): JSX.Element {
  const base = useId();
  const idFor = (name: string) => `${base}-${name}`;

  const [values, setValues] = useState<Record<string, string>>({});
  const [byField, setByField] = useState<Record<string, string>>({});
  const [formError, setFormError] = useState<string | null>(null);
  const focusTarget = useRef<string | null>(null);

  useEffect(() => {
    // In an effect, not inline after setState: the error elements must be in
    // the DOM before focus lands, or aria-describedby points at nothing and
    // the screen reader announces the field without its error.
    if (focusTarget.current === null) return;
    document.getElementById(idFor(focusTarget.current))?.focus();
    focusTarget.current = null;
  });

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        setFormError(null);
        void save(values).catch((error: unknown) => {
          const mapped = mapServerErrors(
            error,
            fields.map((field) => field.name),
          );
          setByField(mapped.byField);
          setFormError(mapped.formError);

          // In `fields` order, not the server's: its object-key order is an
          // implementation detail of its serialiser, and "first error" must
          // mean first on screen.
          focusTarget.current =
            fields.find((field) => mapped.byField[field.name])?.name ?? null;
        });
      }}
    >
      {formError !== null ? <p role="alert">{formError}</p> : null}

      {fields.map((field) => {
        const error = byField[field.name];
        const errorId = `${idFor(field.name)}-error`;

        return (
          <div key={field.name}>
            <label htmlFor={idFor(field.name)}>{field.label}</label>
            <input
              id={idFor(field.name)}
              value={values[field.name] ?? ""}
              aria-invalid={error ? "true" : undefined}
              aria-describedby={error ? errorId : undefined}
              onChange={(event) => {
                const next = event.target.value;
                setValues((prev) => ({ ...prev, [field.name]: next }));
                // The user is replacing the value the server complained about;
                // keeping the message is actively wrong.
                setByField((prev) => {
                  if (!prev[field.name]) return prev;
                  const copy = { ...prev };
                  delete copy[field.name];
                  return copy;
                });
              }}
            />
            {error ? <p id={errorId}>{error}</p> : null}
          </div>
        );
      })}

      <button type="submit">Save</button>
    </form>
  );
}

