// v3rb06_validation_a11y / challenge - reference solution.
import { useActionState, useEffect, useId, useRef, type JSX } from "react";

import { validateSchema, type Schema } from "../ex7/solution";
import { ValidationFailed, mapServerErrors } from "../ex8/solution";

export type SignupState = {
  byField: Record<string, string>;
  formError: string | null;
  attempt: number;
  values: Record<string, string>;
  done: boolean;
};

export function SignupForm({
  schema,
  createAccount,
}: {
  schema: Schema<Record<string, string>>;
  createAccount: (values: Record<string, string>) => Promise<void>;
}): JSX.Element {
  const base = useId();
  const idFor = (name: string) => `${base}-${name}`;
  const errorIdFor = (name: string) => `${base}-${name}-error`;
  const summaryRef = useRef<HTMLDivElement>(null);

  const [state, formAction, isPending] = useActionState<SignupState, FormData>(
    async (previous, formData) => {
      // FormData means no per-field state at all: the DOM is the source, and
      // the action is the single place that decides anything.
      const values: Record<string, string> = {};
      for (const entry of schema) {
        values[entry.field] = String(formData.get(entry.field) ?? "");
      }

      const attempt = previous.attempt + 1;
      const { byField } = validateSchema(values, schema);

      if (Object.keys(byField).length > 0) {
        return { byField, formError: null, attempt, values, done: false };
      }

      try {
        await createAccount(values);
        return { byField: {}, formError: null, attempt, values, done: true };
      } catch (error) {
        const mapped = mapServerErrors(
          error instanceof ValidationFailed ? error : error,
          schema.map((entry) => entry.field),
        );
        return {
          byField: mapped.byField,
          formError: mapped.formError,
          attempt,
          values,
          done: false,
        };
      }
    },
    { byField: {}, formError: null, attempt: 0, values: {}, done: false },
  );

  // Schema order, so the summary matches the form and "the first error" means
  // the same thing to the code and to the user.
  const issues = schema
    .filter((entry) => state.byField[entry.field])
    .map((entry) => ({ ...entry, message: state.byField[entry.field] }));

  useEffect(() => {
    if (state.attempt > 0 && issues.length > 0) summaryRef.current?.focus();
    // Keyed on the attempt counter, so two identical failures both move focus.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [state.attempt]);

  return (
    <div>
      {issues.length > 0 ? (
        // Assertive: it appears only on failure and the user must act.
        <div ref={summaryRef} tabIndex={-1} role="alert">
          <h2>There is a problem</h2>
          <ul>
            {issues.map((issue) => (
              <li key={issue.field}>
                <a
                  href={`#${idFor(issue.field)}`}
                  onClick={(event) => {
                    event.preventDefault();
                    document.getElementById(idFor(issue.field))?.focus();
                  }}
                >
                  {issue.message}
                </a>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      <form action={formAction}>
        {state.formError !== null ? <p role="alert">{state.formError}</p> : null}

        {schema.map((entry) => {
          const error = state.byField[entry.field];
          return (
            <div key={entry.field}>
              <label htmlFor={idFor(entry.field)}>{entry.label}</label>
              <input
                id={idFor(entry.field)}
                name={entry.field}
                // React resets an uncontrolled form after an action returns, so
                // without carrying the submitted values back, a failed submit
                // would erase everything the user typed.
                defaultValue={state.values[entry.field] ?? ""}
                aria-invalid={error ? "true" : undefined}
                aria-describedby={error ? errorIdFor(entry.field) : undefined}
              />
              {error ? <p id={errorIdFor(entry.field)}>{error}</p> : null}
            </div>
          );
        })}

        {/* Never disabled: a disabled button leaves the tab order and explains
            nothing. useActionState queues repeat submissions rather than
            racing them; if double submission were dangerous the answer is an
            idempotency key, not a disabled control. */}
        <button type="submit">{isPending ? "Creating account" : "Create account"}</button>
      </form>

      {/* Polite, and rendered unconditionally so the region exists before its
          content changes. Two assertive regions competing on one submit is a
          real problem: readers announce one and may drop the other. */}
      <div aria-live="polite">{state.done ? "Account created" : ""}</div>
    </div>
  );
}

// v3rb06_validation_a11y / review1 - reference solution.
import { useEffect, useId, useRef, useState, type JSX } from "react";

type Values = { name: string; email: string; amount: string };

const AMOUNTS = ["10", "25", "100"];

function validate(values: Values): Partial<Record<keyof Values, string>> {
  const errors: Partial<Record<keyof Values, string>> = {};
  if (values.name.trim() === "") errors.name = "Enter your name";
  if (values.email.trim() === "") errors.email = "Enter your email address";
  else if (!values.email.includes("@")) errors.email = "Enter a valid email address";
  if (values.amount === "") errors.amount = "Choose an amount";
  return errors;
}

export function DonationForm({ onSubmit }: { onSubmit: (v: Values) => void }): JSX.Element {
  const base = useId();
  const idFor = (name: string) => `${base}-${name}`;
  const errorIdFor = (name: string) => `${base}-${name}-error`;

  const [values, setValues] = useState<Values>({ name: "", email: "", amount: "" });
  const [touched, setTouched] = useState<Partial<Record<keyof Values, boolean>>>({});
  const [attempt, setAttempt] = useState(0);
  const focusTarget = useRef<keyof Values | null>(null);

  const errors = validate(values);
  const shown = (field: keyof Values) => (touched[field] ? errors[field] : undefined);

  useEffect(() => {
    if (focusTarget.current === null) return;
    document.getElementById(idFor(focusTarget.current))?.focus();
    focusTarget.current = null;
  }, [attempt]);

  const text = (field: "name" | "email", label: string) => {
    const error = shown(field);
    return (
      <div>
        {/* Defect 1: a <span> beside an input associates nothing. htmlFor plus
            a real id is the only mechanism that gives a control a name.
            Defect 5: the word is in the label, not only in a red asterisk -
            meaning encoded in a symbol or a colour is meaning nobody else
            receives. */}
        <label htmlFor={idFor(field)}>{label} (required)</label>
        <input
          id={idFor(field)}
          required
          value={values[field]}
          // Defect 3: colour is not information. These two attributes are what
          // make the state and the message reach assistive technology.
          aria-invalid={error ? "true" : undefined}
          aria-describedby={error ? errorIdFor(field) : undefined}
          onChange={(event) =>
            setValues((prev) => ({ ...prev, [field]: event.target.value }))
          }
          onBlur={() => setTouched((prev) => ({ ...prev, [field]: true }))}
        />
        {/* Defect 4: NOT a live region. This text is a description the user can
            query by focusing the field; only something that happens TO them -
            the submit failure below - is announced. */}
        {error ? <p id={errorIdFor(field)}>{error}</p> : null}
      </div>
    );
  };

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        setTouched({ name: true, email: true, amount: true });
        setAttempt((prev) => prev + 1);

        const first = (["name", "email", "amount"] as const).find((f) => errors[f]);
        if (first) {
          focusTarget.current = first;
          return;
        }
        onSubmit(values);
      }}
    >
      {attempt > 0 && Object.keys(errors).length > 0 ? (
        <div role="alert">There is a problem with {Object.keys(errors).length} field(s)</div>
      ) : null}

      {text("name", "Name")}
      {text("email", "Email")}

      {/* Defect 2: a radio group's accessible name comes from the legend and
          from nowhere else. Without it a reader announces three unrelated
          radios with no indication of what they are for. */}
      <fieldset
        aria-invalid={shown("amount") ? "true" : undefined}
        aria-describedby={shown("amount") ? errorIdFor("amount") : undefined}
      >
        <legend>Amount (required)</legend>
        {AMOUNTS.map((amount) => (
          <div key={amount}>
            <input
              id={idFor(`amount-${amount}`)}
              type="radio"
              name="amount"
              value={amount}
              checked={values.amount === amount}
              onChange={() => {
                setValues((prev) => ({ ...prev, amount }));
                setTouched((prev) => ({ ...prev, amount: true }));
              }}
            />
            <label htmlFor={idFor(`amount-${amount}`)}>{amount}</label>
          </div>
        ))}
        {shown("amount") ? <p id={errorIdFor("amount")}>{shown("amount")}</p> : null}
      </fieldset>

      {/* Defect 6: a disabled button leaves the tab order, so a keyboard user
          never finds it, and nothing explains why it is inert. Enable it,
          fail, explain, and move focus. */}
      <button type="submit">Donate</button>
    </form>
  );
}

