## Exercise 1 — offset pagination without off-by-one errors

Edit `ex1/solution.tsx`. Export a pure helper and a component.

```tsx
export function pageWindow(
  current: number,
  totalPages: number,
  span: number,
): number[];

export function Pager({
  total,
  pageSize,
  page,
  onPage,
}: {
  total: number;
  pageSize: number;
  page: number;
  onPage: (next: number) => void;
}): JSX.Element;
```

`pageWindow` returns the page numbers to render — at most `2 * span + 1` of
them, centred on `current`, clamped to `[1, totalPages]`, and **always
`2 * span + 1` long when there are enough pages**. Near an edge the window
slides rather than shrinking: with `span = 2` and `totalPages = 10`,
`current = 1` gives `[1,2,3,4,5]`, not `[1,2,3]`.

`Pager`:

- `totalPages` is `Math.ceil(total / pageSize)`, and `0` when `total` is `0`;
- `<p data-testid="range">Showing {from}–{to} of {total}</p>`, one-based and
  inclusive, where `to` is clamped to `total` — page 5 of 42 items with size 10
  shows `41–42`;
- `Previous` and `Next` buttons, `disabled` at the ends;
- one button per windowed page number, the current one carrying
  `aria-current="page"`;
- when `total` is `0`, render `<p>No results</p>` and no controls at all.

The gate checks `pageWindow` directly with twelve cases including both edges
and `totalPages < 2 * span + 1`, then drives the component.

```
uv run dojo test react v3rb07_large_lists ex1
```

references.solution.tsx:
// v3rb07_large_lists / ex1 - reference solution.
import { type JSX } from "react";

/**
 * At most 2*span+1 numbers, centred on `current`, and the window SLIDES at the
 * edges rather than shrinking - so page 1 of 10 with span 2 gives [1..5], not
 * [1,2,3].
 */
export function pageWindow(current: number, totalPages: number, span: number): number[] {
  if (totalPages <= 0) return [];

  const size = Math.min(span * 2 + 1, totalPages);

  // Two clamps. The first keeps the start on the page list; the second - the
  // one people miss - is what makes the window slide at the right-hand edge
  // instead of running off the end.
  const start = Math.min(Math.max(1, current - span), totalPages - size + 1);

  return Array.from({ length: size }, (_, i) => start + i);
}

export function Pager({
  total,
  pageSize,
  page,
  onPage,
}: {
  total: number;
  pageSize: number;
  page: number;
  onPage: (next: number) => void;
}): JSX.Element {
  // Handled first: with zero pages every calculation below has to defend
  // itself, and an early return is cheaper than five guards.
  if (total === 0) return <p>No results</p>;

  const totalPages = Math.ceil(total / pageSize);
  const current = Math.min(Math.max(1, page), totalPages);

  const from = (current - 1) * pageSize + 1;
  // The min is what stops the last page claiming more items than exist.
  const to = Math.min(current * pageSize, total);

  return (
    <nav>
      <p data-testid="range">
        Showing {from}–{to} of {total}
      </p>

      <button type="button" disabled={current === 1} onClick={() => onPage(current - 1)}>
        Previous
      </button>

      {pageWindow(current, totalPages, 2).map((number) => (
        <button
          key={number}
          type="button"
          // Without this a screen-reader user tabbing ten identical buttons
          // has no way to know which page they are on: the visual highlight
          // conveys nothing.
          aria-current={number === current ? "page" : undefined}
          onClick={() => onPage(number)}
        >
          {number}
        </button>
      ))}

      <button
        type="button"
        disabled={current === totalPages}
        onClick={() => onPage(current + 1)}
      >
        Next
      </button>
    </nav>
  );
}

