## Exercise 2 — cursors, and the rows that arrive twice

Edit `ex2/solution.tsx`. Export a hook.

```tsx
export type Row = { id: string; label: string; rank: number };

export function useCursorList({
  fetchPage,
  pageSize,
}: {
  fetchPage: (
    cursor: string | null,
    limit: number,
    signal: AbortSignal,
  ) => Promise<{ rows: Row[]; nextCursor: string | null }>;
  pageSize: number;
}): {
  rows: Row[];
  loadMore: () => void;
  reset: () => void;
  isLoading: boolean;
  hasMore: boolean;
  duplicatesDropped: number;
};
```

- Loads the first page on mount with `cursor: null`.
- `loadMore` requests with the stored `nextCursor`. It is a no-op while a
  request is in flight or when `nextCursor` is `null`.
- **Appended rows are deduplicated by `id` against the current list**, and
  `duplicatesDropped` counts how many were discarded. The gate returns a page
  whose first row repeats the previous page's last row — which is what happens
  when a row is inserted or updated between requests — and asserts the list has
  no duplicate ids and the counter reads `1`.
- The dedupe must compare against the list **at the moment of the append**, not
  a snapshot captured when the request was sent. The gate proves this by
  resolving two pages out of order.
- `reset()` clears everything and reloads from `null`.
- Requests are aborted on unmount and on `reset`.

```
uv run dojo test react v3rb07_large_lists ex2
```

references.solution.tsx:
// v3rb07_large_lists / ex2 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

export type Row = { id: string; label: string; rank: number };

type State = {
  rows: Row[];
  cursor: string | null;
  hasMore: boolean;
  duplicatesDropped: number;
};

export function useCursorList({
  fetchPage,
  pageSize,
}: {
  fetchPage: (
    cursor: string | null,
    limit: number,
    signal: AbortSignal,
  ) => Promise<{ rows: Row[]; nextCursor: string | null }>;
  pageSize: number;
}): {
  rows: Row[];
  loadMore: () => void;
  reset: () => void;
  isLoading: boolean;
  hasMore: boolean;
  duplicatesDropped: number;
} {
  // Rows and the counter live in one object: they describe one event, and two
  // separate updates would give a frame where they disagree.
  const [state, setState] = useState<State>({
    rows: [],
    cursor: null,
    hasMore: true,
    duplicatesDropped: 0,
  });
  const [isLoading, setIsLoading] = useState(false);

  const loadingRef = useRef(false);
  const controllerRef = useRef<AbortController | null>(null);
  // The abort stops the work; the generation stops any answer that slips
  // through, which is what makes reset safe mid-flight.
  const generation = useRef(0);

  const load = useCallback(
    (cursor: string | null, gen: number) => {
      if (loadingRef.current) return;
      loadingRef.current = true;
      setIsLoading(true);

      controllerRef.current?.abort();
      const controller = new AbortController();
      controllerRef.current = controller;

      fetchPage(cursor, pageSize, controller.signal)
        .then((page) => {
          if (gen !== generation.current) return;

          setState((prev) => {
            // Built INSIDE the updater, so it compares against the list as it
            // is now rather than as it was when the request went out.
            const seen = new Set(prev.rows.map((row) => row.id));
            const fresh = page.rows.filter((row) => !seen.has(row.id));

            return {
              rows: [...prev.rows, ...fresh],
              cursor: page.nextCursor,
              hasMore: page.nextCursor !== null,
              // A duplicate is a property of paginating live data, not a
              // server bug: a row updated across the cursor boundary can
              // legitimately appear in two consecutive pages.
              duplicatesDropped: prev.duplicatesDropped + (page.rows.length - fresh.length),
            };
          });
        })
        .catch(() => {
          /* aborts and failures both leave the list as it was */
        })
        .finally(() => {
          if (gen !== generation.current) return;
          loadingRef.current = false;
          setIsLoading(false);
        });
    },
    [fetchPage, pageSize],
  );

  useEffect(() => {
    const gen = (generation.current += 1);
    load(null, gen);
    return () => {
      generation.current += 1;
      controllerRef.current?.abort();
    };
  }, [load]);

  const loadMore = useCallback(() => {
    if (loadingRef.current || state.cursor === null) return;
    load(state.cursor, generation.current);
  }, [load, state.cursor]);

  const reset = useCallback(() => {
    const gen = (generation.current += 1);
    controllerRef.current?.abort();
    loadingRef.current = false;
    setState({ rows: [], cursor: null, hasMore: true, duplicatesDropped: 0 });
    load(null, gen);
  }, [load]);

  return {
    rows: state.rows,
    loadMore,
    reset,
    isLoading,
    hasMore: state.hasMore,
    duplicatesDropped: state.duplicatesDropped,
  };
}

exercises.hints:
## Hint 1

The reason for a callback ref rather than `useRef` is timing. With `useRef` and
a `useEffect([])`, the effect runs after the first commit — but if the sentinel
is rendered conditionally (hidden while loading, absent when there is no more
data), `ref.current` may be `null` at that moment and nothing re-runs when the
node appears. A callback ref fires *when the node attaches*, which is exactly
when you want to observe it.

## Hint 2

Keep the node in state so the effect can depend on it, or hold the observer
directly in the callback ref. The state version reads more clearly:

```tsx
const [node, setNode] = useState<HTMLElement | null>(null);
useEffect(() => {
  if (!node || !enabled) return;
  const observer = new IntersectionObserver(([entry]) => {
    if (entry.isIntersecting) onReachEndRef.current();
  }, { rootMargin });
  observer.observe(node);
  return () => observer.disconnect();
}, [node, enabled, rootMargin]);
```

`onReachEnd` goes through a ref so a new callback identity does not tear down
and rebuild the observer on every render.

## Hint 3

"Disconnected, not ignored" matters for a specific reason: an observer that
exists but whose callback returns early still runs on every intersection
change, on the main thread, during scroll. Tearing it down when there is
nothing left to load is the difference between a scroll handler that does
nothing and no scroll handler at all.

references.solution.tsx:
// v3rb07_large_lists / ex3 - reference solution.
import { useCallback, useEffect, useRef, useState } from "react";

export function useReachEnd({
  onReachEnd,
  enabled,
  rootMargin = "200px",
}: {
  onReachEnd: () => void;
  enabled: boolean;
  rootMargin?: string;
}): (node: HTMLElement | null) => void {
  // The node lives in state so the effect can depend on it. A useRef plus a
  // useEffect([]) runs before a conditionally-rendered sentinel exists, and
  // nothing re-runs when it appears.
  const [node, setNode] = useState<HTMLElement | null>(null);

  // Through a ref so a new callback identity does not tear down and rebuild
  // the observer on every render of the parent.
  const handler = useRef(onReachEnd);
  handler.current = onReachEnd;

  useEffect(() => {
    // Disconnected, not ignored: an observer whose callback returns early
    // still runs on the main thread on every intersection change during
    // scroll.
    if (node === null || !enabled) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        // Fires once immediately with the current state, which is what you
        // want when the first page did not fill the viewport. The caller's
        // in-flight guard is what stops it becoming "load everything".
        if (entry.isIntersecting) handler.current();
      },
      // Start the load a scroll-flick before the user arrives.
      { rootMargin },
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, [node, enabled, rootMargin]);

  return useCallback((next: HTMLElement | null) => setNode(next), []);
}

// v3rb07_large_lists / ex4 - reference solution.
import { useRef, type JSX } from "react";

import { useReachEnd } from "../ex3/solution";

const MAX_AUTO_LOADS = 3;

export function Feed({
  rows,
  hasMore,
  isLoading,
  onLoadMore,
}: {
  rows: { id: string; label: string }[];
  hasMore: boolean;
  isLoading: boolean;
  onLoadMore: () => void;
}): JSX.Element {
  // Bounds DOM growth, keeps the footer reachable, and gives the user a moment
  // to decide whether they want more.
  const autoLoads = useRef(0);
  const canAuto = hasMore && !isLoading && autoLoads.current < MAX_AUTO_LOADS;

  const sentinelRef = useReachEnd({
    enabled: canAuto,
    onReachEnd: () => {
      autoLoads.current += 1;
      onLoadMore();
    },
  });

  return (
    <div>
      <ul>
        {rows.map((row, index) => (
          <li
            key={row.id}
            aria-posinset={index + 1}
            // -1 is the specified way to say "the total is unknown", and with
            // cursor pagination it genuinely is. A wrong number is worse: the
            // reader announces "3 of 20" for a list of two thousand.
            aria-setsize={-1}
          >
            {row.label}
          </li>
        ))}
      </ul>

      {hasMore ? (
        <button
          type="button"
          // The ref goes on the BUTTON. One node, one purpose: there is no
          // invisible trigger that exists for the mouse and not the keyboard,
          // and the observer becomes a convenience over a working control.
          ref={sentinelRef}
          onClick={() => {
            autoLoads.current = 0; // an explicit click buys three more
            onLoadMore();
          }}
        >
          {isLoading ? "Loading" : "Load more"}
        </button>
      ) : null}

      {/* Announce the count, not the rows: one short utterance saying that
          something happened and how much. */}
      <div aria-live="polite">{rows.length > 0 ? `Showing ${rows.length} items` : ""}</div>
    </div>
  );
}

