// v3rb07_large_lists / ex5 - reference solution.
import { useState, type JSX } from "react";

const clamp = (value: number, low: number, high: number) =>
  Math.min(Math.max(value, low), high);

export function windowRange({
  scrollTop,
  viewportHeight,
  rowHeight,
  count,
  overscan,
}: {
  scrollTop: number;
  viewportHeight: number;
  rowHeight: number;
  count: number;
  overscan: number;
}): { start: number; end: number; offsetY: number } {
  const first = Math.floor(scrollTop / rowHeight);
  const start = clamp(first - overscan, 0, count);
  const visible = Math.ceil(viewportHeight / rowHeight);
  // Clamped to count, or slice() quietly returns fewer rows and the last
  // screen shows blank space under the final row.
  const end = clamp(start + visible + overscan * 2, 0, count);

  return { start, end, offsetY: start * rowHeight };
}

export function VirtualList({
  items,
  rowHeight,
  height,
  overscan = 3,
  renderCount,
}: {
  items: { id: string; label: string }[];
  rowHeight: number;
  height: number;
  overscan?: number;
  renderCount?: { current: number };
}): JSX.Element {
  if (renderCount) renderCount.current += 1;

  const [scrollTop, setScrollTop] = useState(0);

  const { start, end, offsetY } = windowRange({
    scrollTop,
    viewportHeight: height,
    rowHeight,
    count: items.length,
    overscan,
  });

  return (
    // The viewport: fixed height, owns the scroll.
    <div
      data-testid="viewport"
      style={{ height, overflowY: "auto" }}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
    >
      {/* The spacer: full content height, exists only so the browser's
          scrollbar reflects the DATA rather than the window. Remove it and the
          scrollbar thinks there are seventeen rows. */}
      <div
        data-testid="spacer"
        style={{ height: items.length * rowHeight, position: "relative" }}
      >
        {/* transform, not top: `top` triggers layout on every scroll event;
            a transform is handled by the compositor and skips layout and
            paint entirely. */}
        <div style={{ transform: `translateY(${offsetY}px)` }}>
          <ul style={{ margin: 0, padding: 0, listStyle: "none" }}>
            {items.slice(start, end).map((item) => (
              <li key={item.id} style={{ height: rowHeight }}>
                {item.label}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}

