// v3rb07_large_lists / ex6 - reference solution.
import { useEffect, useRef, useState, type JSX } from "react";

export class OffsetCache {
  private heights: number[];
  /** offsets[i] is the top of row i; offsets[count] is the total height. */
  private offsets: number[];
  private estimate: number;

  constructor(count: number, estimate: number) {
    this.estimate = estimate;
    this.heights = new Array<number>(count).fill(estimate);
    this.offsets = new Array<number>(count + 1).fill(0);
    this.rebuildFrom(0);
  }

  private rebuildFrom(index: number): void {
    for (let i = index; i < this.heights.length; i++) {
      this.offsets[i + 1] = this.offsets[i] + this.heights[i];
    }
  }

  offsetOf(index: number): number {
    return this.offsets[Math.min(index, this.offsets.length - 1)];
  }

  totalHeight(): number {
    return this.offsets[this.offsets.length - 1];
  }

  /** Binary search: a linear scan over 100,000 rows on every scroll event is
   *  the difference between smooth and unusable. */
  indexAt(scrollTop: number): number {
    let low = 0;
    let high = this.heights.length - 1;
    while (low < high) {
      const mid = (low + high + 1) >> 1;
      if (this.offsets[mid] <= scrollTop) low = mid;
      else high = mid - 1;
    }
    return low;
  }

  /** Returns whether anything changed. The caller re-renders only when it did,
   *  which is what stops ResizeObserver - which fires on every layout,
   *  including ones our own correction caused - from looping forever. */
  measure(index: number, height: number): boolean {
    if (index < 0 || index >= this.heights.length) return false;
    if (this.heights[index] === height) return false;
    this.heights[index] = height;
    // Only from here forward: everything above is unaffected.
    this.rebuildFrom(index);
    return true;
  }

  setCount(count: number): void {
    while (this.heights.length < count) this.heights.push(this.estimate);
    this.heights.length = count;
    this.offsets.length = count + 1;
    this.rebuildFrom(0);
  }
}

export function VariableList({
  items,
  estimate,
  height,
  overscan = 3,
}: {
  items: { id: string; label: string; lines: number }[];
  estimate: number;
  height: number;
  overscan?: number;
}): JSX.Element {
  const cacheRef = useRef<OffsetCache | null>(null);
  if (cacheRef.current === null) cacheRef.current = new OffsetCache(items.length, estimate);
  const cache = cacheRef.current;
  cache.setCount(items.length);

  const [scrollTop, setScrollTop] = useState(0);
  // Bumped only when a measurement actually changed an offset.
  const [, setVersion] = useState(0);

  const first = cache.indexAt(scrollTop);
  const start = Math.max(0, first - overscan);
  let end = start;
  while (end < items.length && cache.offsetOf(end) < scrollTop + height) end++;
  end = Math.min(items.length, end + overscan);

  const observerRef = useRef<ResizeObserver | null>(null);
  const nodes = useRef(new Map<Element, number>());

  useEffect(() => {
    // A ResizeObserver runs in the same frame rather than after paint, so the
    // correction is invisible - and it catches heights that change AFTER
    // mount, which a measure-on-mount effect never sees.
    const observer = new ResizeObserver((entries) => {
      let changed = false;
      for (const entry of entries) {
        const index = nodes.current.get(entry.target);
        if (index === undefined) continue;
        if (cache.measure(index, entry.contentRect.height)) changed = true;
      }
      if (changed) setVersion((v) => v + 1);
    });
    observerRef.current = observer;
    return () => observer.disconnect();
  }, [cache]);

  const attach = (index: number) => (node: HTMLElement | null) => {
    const observer = observerRef.current;
    if (!observer) return;
    if (node === null) return;
    nodes.current.set(node, index);
    observer.observe(node);
  };

  return (
    <div
      data-testid="viewport"
      style={{ height, overflowY: "auto" }}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
    >
      <div style={{ height: cache.totalHeight(), position: "relative" }}>
        {items.slice(start, end).map((item, i) => {
          const index = start + i;
          return (
            <div
              key={item.id}
              ref={attach(index)}
              // Absolutely positioned per row rather than one translated
              // wrapper: with variable heights each row's top is its own
              // number.
              style={{ position: "absolute", top: cache.offsetOf(index), left: 0, right: 0 }}
            >
              {item.label}
            </div>
          );
        })}
      </div>
    </div>
  );
}

