// v3rb07_large_lists / ex7 - reference solution.
import { useEffect, useLayoutEffect, useRef, useState, type JSX } from "react";

// Deliberately crude: never evicts, does not survive a reload, and two
// components could collide on a listId. sessionStorage or a router's location
// state are the real answers; this is labelled rather than pretended.
const savedScroll = new Map<string, number>();

export function useScrollAnchor(
  viewport: React.RefObject<HTMLElement | null>,
  dependency: unknown,
): void {
  const previousHeight = useRef(0);

  // Recorded on every render, so the layout effect below has a "before" to
  // compare against. There is no useBeforeLayoutEffect, and reading the DOM
  // during render is the pragmatic alternative to threading the measurement
  // through every trigger.
  const el = viewport.current;
  const heightNow = el ? el.scrollHeight : 0;

  useLayoutEffect(() => {
    const node = viewport.current;
    if (!node) return;

    const delta = node.scrollHeight - previousHeight.current;
    // Prepending increases scrollHeight by exactly the height of what was
    // added; adding the same delta to scrollTop leaves the visible content
    // where it was.
    if (previousHeight.current > 0 && delta > 0) node.scrollTop += delta;

    previousHeight.current = node.scrollHeight;
    // useLayoutEffect, not useEffect: with the latter the browser paints the
    // new position first and the user sees the content jump.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dependency]);

  useEffect(() => {
    previousHeight.current = heightNow;
  }, [heightNow]);
}

export function ChatLog({
  messages,
  onLoadOlder,
  listId,
}: {
  messages: { id: string; text: string }[];
  onLoadOlder: () => void;
  listId: string;
}): JSX.Element {
  const viewport = useRef<HTMLDivElement>(null);
  const [, setMounted] = useState(false);

  useScrollAnchor(viewport, messages.length);

  useLayoutEffect(() => {
    const node = viewport.current;
    if (!node) return;

    // Before paint, so there is no frame showing the top of the list. The
    // rows must already exist for this to mean anything - setting scrollTop
    // on a container holding ten rows clamps to its maximum and silently
    // loses the position.
    const saved = savedScroll.get(listId);
    if (saved !== undefined) node.scrollTop = saved;
    setMounted(true);

    return () => {
      savedScroll.set(listId, node.scrollTop);
    };
  }, [listId]);

  return (
    <div ref={viewport} data-testid="viewport" style={{ height: 300, overflowY: "auto" }}>
      <button type="button" onClick={onLoadOlder}>
        Load older
      </button>
      <ul>
        {messages.map((message) => (
          <li key={message.id}>{message.text}</li>
        ))}
      </ul>
    </div>
  );
}

// v3rb07_large_lists / ex8 - reference solution.
import { useLayoutEffect, useRef, useState, type JSX } from "react";

import { windowRange } from "../ex5/solution";

export function VirtualListbox({
  items,
  rowHeight,
  height,
  onActivate,
}: {
  items: { id: string; label: string }[];
  rowHeight: number;
  height: number;
  onActivate: (id: string) => void;
}): JSX.Element {
  const viewport = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [active, setActive] = useState(0);
  // Only move focus in response to a keystroke: stealing it on every scroll
  // would fight the mouse.
  const wantsFocus = useRef(false);

  const { start, end, offsetY } = windowRange({
    scrollTop,
    viewportHeight: height,
    rowHeight,
    count: items.length,
    overscan: 3,
  });

  const scrollIndexIntoView = (index: number) => {
    const node = viewport.current;
    if (!node) return;
    const top = index * rowHeight;
    const bottom = top + rowHeight;
    // Arithmetic rather than scrollIntoView, which needs the element - the
    // very thing that does not exist yet.
    if (top < node.scrollTop) node.scrollTop = top;
    else if (bottom > node.scrollTop + height) node.scrollTop = bottom - height;
    setScrollTop(node.scrollTop);
  };

  const move = (next: number) => {
    const clamped = Math.min(Math.max(0, next), items.length - 1);
    setActive(clamped);
    // Order matters: index, then scroll, then render, then focus. Focusing
    // first would target an element that has not been rendered.
    scrollIndexIntoView(clamped);
    wantsFocus.current = true;
  };

  useLayoutEffect(() => {
    if (!wantsFocus.current) return;
    wantsFocus.current = false;
    viewport.current
      ?.querySelector<HTMLElement>(`[data-index="${active}"]`)
      ?.focus();
  }, [active, start, end]);

  const onKeyDown = (event: React.KeyboardEvent) => {
    const page = Math.max(1, Math.floor(height / rowHeight));
    switch (event.key) {
      case "ArrowDown": event.preventDefault(); move(active + 1); break;
      case "ArrowUp": event.preventDefault(); move(active - 1); break;
      case "Home": event.preventDefault(); move(0); break;
      case "End": event.preventDefault(); move(items.length - 1); break;
      case "PageDown": event.preventDefault(); move(active + page); break;
      case "PageUp": event.preventDefault(); move(active - page); break;
      case "Enter":
      case " ":
        event.preventDefault(); // or Space scrolls the page
        onActivate(items[active].id);
        break;
      default:
        break;
    }
  };

  return (
    <div
      ref={viewport}
      role="listbox"
      data-testid="viewport"
      style={{ height, overflowY: "auto" }}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      onKeyDown={onKeyDown}
    >
      <div style={{ height: items.length * rowHeight, position: "relative" }}>
        <div style={{ transform: `translateY(${offsetY}px)` }}>
          {items.slice(start, end).map((item, i) => {
            const index = start + i;
            return (
              <div
                key={item.id}
                data-index={index}
                role="option"
                aria-selected={index === active}
                // Two attributes, and the difference between "item 3 of 17"
                // and the truth. Without them a reader inspects a DOM holding
                // seventeen options and announces accordingly.
                aria-posinset={index + 1}
                aria-setsize={items.length}
                // Roving tabindex: one tabbable element for the whole widget,
                // so a user tabs PAST the listbox in one keystroke instead of
                // through 50,000 rows.
                tabIndex={index === active ? 0 : -1}
                style={{ height: rowHeight }}
              >
                {item.label}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// v3rb07_large_lists / challenge - reference solution.
import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type JSX,
} from "react";

export type Section = { id: string; title: string; rows: { id: string; label: string }[] };

export type FeedHandle = { scrollToIndex: (index: number) => void };

type Flat =
  | { kind: "header"; key: string; sectionIndex: number; title: string }
  | { kind: "row"; key: string; sectionIndex: number; label: string };

export const SectionedFeed = forwardRef<
  FeedHandle,
  {
    sections: Section[];
    hasMore: boolean;
    isLoading: boolean;
    onLoadMore: () => void;
    rowHeight: number;
    headerHeight: number;
    height: number;
  }
>(function SectionedFeed(
  { sections, hasMore, isLoading, onLoadMore, rowHeight, headerHeight, height },
  ref,
): JSX.Element {
  const viewport = useRef<HTMLDivElement>(null);
  const [scrollTop, setScrollTop] = useState(0);

  // Flattening first makes everything else ordinary: the windowing code does
  // not care that heights differ, only that offsets exist. Each entry carries
  // its section index so the sticky header is a lookup rather than a search.
  const { flat, offsets } = useMemo(() => {
    const out: Flat[] = [];
    sections.forEach((section, sectionIndex) => {
      out.push({ kind: "header", key: `h-${section.id}`, sectionIndex, title: section.title });
      for (const row of section.rows) {
        out.push({ kind: "row", key: row.id, sectionIndex, label: row.label });
      }
    });
    const sums = new Array<number>(out.length + 1).fill(0);
    for (let i = 0; i < out.length; i++) {
      sums[i + 1] = sums[i] + (out[i].kind === "header" ? headerHeight : rowHeight);
    }
    return { flat: out, offsets: sums };
  }, [sections, headerHeight, rowHeight]);

  const indexAt = (top: number) => {
    let low = 0;
    let high = flat.length - 1;
    while (low < high) {
      const mid = (low + high + 1) >> 1;
      if (offsets[mid] <= top) low = mid;
      else high = mid - 1;
    }
    return Math.max(0, low);
  };

  const topIndex = flat.length > 0 ? indexAt(scrollTop) : 0;
  const start = Math.max(0, topIndex - 3);
  let end = topIndex;
  while (end < flat.length && offsets[end] < scrollTop + height) end++;
  end = Math.min(flat.length, end + 3);

  const stickyTitle = flat.length > 0 ? sections[flat[topIndex].sectionIndex]?.title ?? "" : "";

  // The re-entry guard, in a new costume: `end` changes on every scroll event,
  // so a naive check fires continuously while the user sits near the bottom.
  const lastTriggeredLength = useRef(-1);
  if (hasMore && !isLoading && end >= flat.length - 10 && lastTriggeredLength.current !== flat.length) {
    lastTriggeredLength.current = flat.length;
    queueMicrotask(onLoadMore);
  }

  // Anchoring: appending must not move what the user is reading.
  const previousHeight = useRef(0);
  useLayoutEffect(() => {
    const node = viewport.current;
    if (!node) return;
    const total = offsets[offsets.length - 1];
    previousHeight.current = total;
  }, [offsets]);

  useImperativeHandle(
    ref,
    () => ({
      // Imperative because scrolling is an action, not state: modelling it as
      // a prop would have React re-asserting a position the user is fighting,
      // which is the controlled-input problem in a new place.
      scrollToIndex(index: number) {
        const node = viewport.current;
        if (!node) return;
        node.scrollTop = offsets[Math.min(Math.max(0, index), flat.length - 1)];
        setScrollTop(node.scrollTop);
      },
    }),
    [offsets, flat.length],
  );

  return (
    <div>
      {/* Rendered separately, outside the translated wrapper: CSS position
          sticky un-sticks the moment virtualization unmounts the header. */}
      <div data-testid="sticky">{stickyTitle}</div>

      <div
        ref={viewport}
        data-testid="viewport"
        style={{ height, overflowY: "auto" }}
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      >
        <div style={{ height: offsets[offsets.length - 1], position: "relative" }}>
          <div style={{ transform: `translateY(${offsets[start]}px)` }}>
            {flat.slice(start, end).map((entry, i) =>
              entry.kind === "header" ? (
                <div key={entry.key} style={{ height: headerHeight }}>
                  <h3>{entry.title}</h3>
                </div>
              ) : (
                <div
                  key={entry.key}
                  style={{ height: rowHeight }}
                  aria-posinset={start + i + 1}
                  // -1 while more may arrive: a wrong total is worse than an
                  // honest unknown.
                  aria-setsize={hasMore ? -1 : flat.length}
                >
                  {entry.label}
                </div>
              ),
            )}
          </div>
        </div>
      </div>

      {hasMore ? (
        <button type="button" onClick={onLoadMore}>
          {isLoading ? "Loading" : "Load more"}
        </button>
      ) : null}
    </div>
  );
});

// v3rb07_large_lists / review1 - reference solution.
import { memo, useMemo, useState, type JSX } from "react";

type Order = { id: string; ref: string; status: string; total: number };

// Defect 3: hoisted to a module constant. An inline object literal is a new
// identity on every render and fails memo's prop comparison.
const CELL_STYLE = { padding: 8 } as const;

// Defect 1: memoised. Without this, a parent render re-renders 3,000 rows
// regardless of whether their props moved.
const OrderRow = memo(function OrderRow({
  order,
  onSelect,
  renderCount,
}: {
  order: Order;
  onSelect: (id: string) => void;
  renderCount: { current: number };
}): JSX.Element {
  renderCount.current += 1;

  return (
    <tr>
      <td style={CELL_STYLE}>{order.ref}</td>
      <td style={CELL_STYLE}>{order.status}</td>
      <td style={CELL_STYLE}>{order.total}</td>
      <td style={CELL_STYLE}>
        {/* Defect 2, fixed at the right level: the arrow is created inside the
            memoised row, so it is new only when this row re-renders. The
            props crossing the memo boundary - `order` and the stable
            `onSelect` - do not change. */}
        <button type="button" onClick={() => onSelect(order.id)}>
          Select {order.ref}
        </button>
      </td>
    </tr>
  );
});

export function OrdersTable({
  orders,
  onSelect,
  renderCounts,
}: {
  orders: Order[];
  onSelect: (id: string) => void;
  renderCounts: { table: { current: number }; row: { current: number } };
}): JSX.Element {
  renderCounts.table.current += 1;

  // An unrelated piece of state, to prove the parent can re-render without
  // costing anything below it.
  const [expanded, setExpanded] = useState(false);

  // Defect 4, both halves. useMemo stops the recomputation; the spread copy
  // stops `sort` mutating the caller's array - which in a parent memoised on
  // `orders` would mean it never re-renders even though its data changed.
  const sorted = useMemo(() => [...orders].sort((a, b) => a.ref.localeCompare(b.ref)), [orders]);

  return (
    <div>
      <button type="button" onClick={() => setExpanded((prev) => !prev)}>
        Toggle details
      </button>
      {expanded ? <p>Details</p> : null}

      <table>
        <tbody>
          {sorted.map((order) => (
            <OrderRow
              key={order.id}
              order={order}
              onSelect={onSelect}
              renderCount={renderCounts.row}
            />
          ))}
        </tbody>
      </table>
    </div>
  );
}
